func buflist_setfpos(buf *S_file_buffer, win *S_window_S, lnum linenr_T, col colnr_T, copy_options int32) {
	var wip *S_wininfo_S = buf.b_wininfo
	for ; wip != nil; wip = wip.wi_next {
		if wip.wi_win == win {
			break
		}
	}
	if wip == nil {
		wip = new(S_wininfo_S)
		wip.wi_win = win
		if lnum == 0 {
			lnum = 1
		}
	} else {
		if wip.wi_prev != nil {
			wip.wi_prev.wi_next = wip.wi_next
		} else {
			buf.b_wininfo = wip.wi_next
		}
		if wip.wi_next != nil {
			wip.wi_next.wi_prev = wip.wi_prev
		}
		if (copy_options != 0) && (wip.wi_optset != 0) {
			clear_winopt(&wip.wi_opt)
		}
	}
	if lnum != 0 {
		wip.wi_fpos.lnum = lnum
		wip.wi_fpos.col = col
	}
	if (copy_options != 0) && (win != nil) {
		copy_winopt(&win.w_onebuf_opt, &wip.wi_opt)
		wip.wi_optset = TRUE
	}
	wip.wi_next = buf.b_wininfo
	buf.b_wininfo = wip
	wip.wi_prev = nil
	if wip.wi_next != nil {
		wip.wi_next.wi_prev = wip
	}
}

