func do_cmdline(cmdline Ptr[byte], fgetline func(int32, int32, getline_opt_T) Ptr[byte], flags int32) bool {
	var next_cmdline Ptr[byte]
	var cmdline_copy Ptr[byte] = Ptr[byte]{}
	var used_getline bool = false
	var msg_didout_before_start int32 = 0
	var count int32 = 0
	var did_inc_RedrawingDisabled bool = false
	var retval bool = true
	if do_cmdline_call_depth >= 200 {
		emsg(gettext_(e_command_too_recursive))
		return false
	}
	do_cmdline_call_depth++
	did_emsg = FALSE
	if ((flags & DOCMD_KEYTYPED) == 0) && ((flags & DOCMD_GETEXLINE) == 0) {
		KeyTyped = FALSE
	}
	next_cmdline = cmdline
	for {
		if next_cmdline.Nil() {
			did_emsg = FALSE
		}
		if next_cmdline.Nil() {
			if (count == 1) && ((flags & DOCMD_GETEXLINE) != 0) {
				msg_didout = TRUE
			}
			var t1 bool = fgetline == nil
			if !t1 {
				next_cmdline = fgetline(':', 0, GETLINE_CONCAT_CONT)
				t1 = next_cmdline.Nil()
			}
			if t1 {
				if (KeyTyped != 0) && ((flags & DOCMD_REPEAT) == 0) {
					need_wait_return = FALSE
				}
				retval = false
				break
			}
			used_getline = true
			if flags&DOCMD_KEEPLINE != 0 {
				if count == 0 {
					repeat_cmdline = vim_strsave(next_cmdline)
				} else {
					repeat_cmdline = Ptr[byte]{}
				}
			}
		} else if cmdline_copy.Nil() {
			next_cmdline = vim_strsave(next_cmdline)
		}
		cmdline_copy = next_cmdline
		var t2 int32 = count
		count++
		if t2 == 0 {
			if ((flags & DOCMD_NOWAIT) == 0) && (do_cmdline_recursive == 0) {
				msg_didout_before_start = msg_didout
				msg_didany = FALSE
				msg_start()
				msg_scroll = TRUE
				no_wait_return++
				RedrawingDisabled++
				did_inc_RedrawingDisabled = true
			}
		}
		if ((p_verbose >= 15) && !GaData[estack_T](&exestack).Ref(int(exestack.ga_len-1)).es_name.Nil()) || (p_verbose >= 16) {
			msg_verbose_cmd(GaData[estack_T](&exestack).Ref(int(exestack.ga_len-1)).es_lnum, cmdline_copy)
		}
		do_cmdline_recursive++
		next_cmdline = do_one_cmd(&cmdline_copy, flags, fgetline)
		do_cmdline_recursive--
		if next_cmdline.Nil() {
			cmdline_copy = Ptr[byte]{}
			if ((flags & DOCMD_GETEXLINE) != 0) && !new_last_cmdline.Nil() {
				last_cmdline = new_last_cmdline
				new_last_cmdline = Ptr[byte]{}
			}
		} else {
			Memmove(cmdline_copy, next_cmdline, int(musl_strlen(next_cmdline)+1))
			next_cmdline = cmdline_copy
		}
		if !(((got_int == 0) && !(((did_emsg != 0) && used_getline) && ((flags & DOCMD_GETEXLINE) != 0))) && (!next_cmdline.Nil() || ((flags & DOCMD_REPEAT) != 0))) {
			break
		}
	}
	if did_inc_RedrawingDisabled {
		if RedrawingDisabled > 0 {
			RedrawingDisabled--
		}
		no_wait_return--
		msg_scroll = FALSE
		if B2i(retval) == FAIL {
			need_wait_return = FALSE
			msg_didany = FALSE
		} else if need_wait_return != 0 {
			msg_didout |= msg_didout_before_start
			wait_return(FALSE)
		}
	}
	do_cmdline_call_depth--
	return (retval)
}

func do_one_cmd(cmdlinep *Ptr[byte], flags int32, fgetline func(int32, int32, getline_opt_T) Ptr[byte]) Ptr[byte] {
	var p Ptr[byte]
	var lnum linenr_T
	var n int64
	var errormsg Ptr[byte]
	var after_modifier Ptr[byte]
	var ea S_exarg
	var save_cmdmod cmdmod_T
	var save_reg_executing int32
	var save_pending_end_reg_executing int32
	var cmd Ptr[byte]
	var sourcing int32
	var did_append_cmd bool
	var t1 bool
	var t2 Ptr[byte]

	errormsg = Ptr[byte]{}
	after_modifier = Ptr[byte]{}
	save_reg_executing = reg_executing
	save_pending_end_reg_executing = pending_end_reg_executing
	sourcing = flags & DOCMD_VERBOSE
	did_append_cmd = false
	ea = S_exarg{}
	ea.line1 = 1
	ea.line2 = 1
	if quitmore != 0 {
		quitmore--
	}
	save_cmdmod = cmdmod
	if (int32((*cmdlinep).At(0)) == '#') && (int32((*cmdlinep).At(1)) == '!') {
		goto doend
	}
	ea.cmd = (*cmdlinep)
	ea.cmdlinep = cmdlinep
	ea.ea_getline = fgetline
	if !parse_command_modifiers(&ea, &errormsg, &cmdmod, FALSE) {
		goto doend
	}
	apply_cmdmod(&cmdmod)
	after_modifier = ea.cmd
	cmd = ea.cmd
	ea.cmd = skip_range(ea.cmd, TRUE, nil)
	p = find_ex_command(&ea, nil)
	ea.cmd = cmd
	if ea.cmdidx != CMD_SIZE {
		ea.addr_type = cmdnames[int(ea.cmdidx)].cmd_addr_type
	} else {
		ea.addr_type = ADDR_LINES
	}
	if !parse_cmd_address(&ea, &errormsg, FALSE) {
		goto doend
	}
	ea.cmd = skipwhite(ea.cmd)
	for int32(ea.cmd.Get()) == ':' {
		ea.cmd = skipwhite(ea.cmd.Add(1))
	}
	t1 = int32(ea.cmd.Get()) == NUL
	if !t1 {
		ea.nextcmd = check_nextcmd(ea.cmd)
		t1 = !ea.nextcmd.Nil()
	}
	if t1 {
		errormsg = ex_range_without_command(&ea)
		goto doend
	}
	if p.Nil() {
		errormsg = gettext_(e_ambiguous_use_of_user_defined_command)
		goto doend
	}
	if ((int32(p.Get()) == '!') && (int32(ea.cmd.At(1)) == 0151)) && (int32(ea.cmd.At(0)) == 78) {
		errormsg = uc_fun_cmd()
		goto doend
	}
	if ea.cmdidx == CMD_SIZE {
		musl_strcpy(IObuff, gettext_(e_not_an_editor_command))
		if sourcing == 0 {
			if !after_modifier.Nil() {
				append_command(after_modifier)
			} else {
				append_command((*cmdlinep))
			}
			did_append_cmd = true
		}
		errormsg = IObuff
		goto doend
	}
	if (((int32(p.Get()) == '!') && (ea.cmdidx != CMD_substitute)) && (ea.cmdidx != CMD_smagic)) && (ea.cmdidx != CMD_snomagic) {
		p = p.Add(1)
		ea.forceit = TRUE
	} else {
		ea.forceit = FALSE
	}
	ea.argt = int64(cmdnames[int(ea.cmdidx)].cmd_argt)
	if (curbuf.b_p_ma == 0) && ((ea.argt & EX_MODIFY) != 0) {
		errormsg = gettext_(e_cannot_make_changes_modifiable_is_off)
		goto doend
	}
	if text_locked() && ((ea.argt & EX_LOCK_OK) == 0) {
		errormsg = gettext_(get_text_locked_msg())
		goto doend
	}
	if ((ea.argt & (EX_CMDWIN | EX_LOCK_OK)) == 0) && curbuf_locked() {
		goto doend
	}
	if ((ea.argt & EX_RANGE) == 0) && (ea.addr_count > 0) {
		errormsg = gettext_(e_no_range_allowed)
		goto doend
	}
	if ((ea.argt & EX_BANG) == 0) && (ea.forceit != 0) {
		errormsg = gettext_(e_no_bang_allowed)
		goto doend
	}
	if ea.argt&EX_RANGE != 0 {
		if (global_busy == 0) && (ea.line1 > ea.line2) {
			if msg_silent == 0 {
				if sourcing != 0 {
					errormsg = gettext_(e_backwards_range_given)
					goto doend
				}
				if ask_yesno(gettext_(S("Backwards range given, OK to swap")), FALSE) != 'y' {
					goto doend
				}
			}
			lnum = ea.line1
			ea.line1 = ea.line2
			ea.line2 = lnum
		}
		errormsg = invalid_range(&ea)
		if !errormsg.Nil() {
			goto doend
		}
	}
	if (ea.addr_type == ADDR_OTHER) && (ea.addr_count == 0) {
		ea.line2 = 1
	}
	correct_range(&ea)
	ea.arg = skipwhite(p)
	if (ea.cmdidx == CMD_lshift) || (ea.cmdidx == CMD_rshift) {
		ea.amount = 1
		for int32(ea.arg.Get()) == int32(ea.cmd.Get()) {
			ea.arg = ea.arg.Add(1)
			ea.amount++
		}
		ea.arg = skipwhite(ea.arg)
	}
	if ea.argt&EX_CMDARG != 0 {
		ea.do_ecmd_cmd = getargcmd(&ea.arg)
	}
	if ea.argt&EX_TRLBAR != 0 {
		separate_nextcmd(&ea, FALSE)
	} else if (ea.cmdidx == CMD_global) || (ea.cmdidx == CMD_vglobal) {
		p = ea.arg
		for ; p.Get() != 0; p = p.Add(1) {
			if (int32(p.Get()) == 92) && (int32(p.At(1)) == 10) {
				Memmove(p, p.Add(1), int(musl_strlen(p.Add(1))+1))
			} else if int32(p.Get()) == 10 {
				ea.nextcmd = p.Add(1)
				p.Put(NUL)
				break
			}
		}
	}
	if ((ea.argt & EX_DFLALL) != 0) && (ea.addr_count == 0) {
		address_default_all(&ea)
	}
	if (((ea.argt & EX_REGSTR) != 0) && (int32(ea.arg.Get()) != NUL)) && !(((ea.argt & EX_COUNT) != 0) && ((uint32(ea.arg.Get()) - '0') < 10)) {
		if (int32(ea.arg.Get()) == '*') || (int32(ea.arg.Get()) == '+') {
			errormsg = gettext_(e_invalid_register_name)
			goto doend
		}
		if valid_yank_reg(int32(ea.arg.Get()), B2i(((ea.cmdidx != CMD_put) && (ea.cmdidx != CMD_iput)))) {
			t2 = ea.arg
			ea.arg = ea.arg.Add(1)
			ea.regname = int32(t2.Get())
			ea.arg = skipwhite(ea.arg)
		}
	}
	if ((ea.argt & EX_COUNT) != 0) && ((uint32(ea.arg.Get()) - '0') < 10) {
		n = getdigits_quoted(&ea.arg)
		ea.arg = skipwhite(ea.arg)
		if (n <= 0) && ((ea.argt & EX_ZEROR) == 0) {
			errormsg = gettext_(e_positive_count_required)
			goto doend
		}
		if ea.addr_type != ADDR_LINES {
			ea.line2 = n
			if ea.addr_count == 0 {
				ea.addr_count = 1
			}
		} else {
			ea.line1 = ea.line2
			if ea.line2 >= (LONG_MAX - (n - 1)) {
				ea.line2 = LONG_MAX
			} else {
				ea.line2 += n - 1
			}
			ea.addr_count++
			if ea.line2 > curbuf.b_ml.ml_line_count {
				ea.line2 = curbuf.b_ml.ml_line_count
			}
		}
	}
	if ea.argt&EX_FLAGS != 0 {
		get_flags(&ea)
	}
	if ((ea.argt & EX_EXTRA) == 0) && (int32(ea.arg.Get()) != NUL) {
		errormsg = ex_errmsg(e_trailing_characters_str, ea.arg)
		goto doend
	}
	if ((ea.argt & EX_NEEDARG) != 0) && (int32(ea.arg.Get()) == NUL) {
		errormsg = gettext_(e_argument_required)
		goto doend
	}
	cmdnames[int(ea.cmdidx)].cmd_func(&ea)
	if !ea.errmsg.Nil() {
		errormsg = ea.errmsg
	}
doend:
	if curwin.w_cursor.lnum == 0 {
		curwin.w_cursor.lnum = 1
		curwin.w_cursor.col = 0
	}
	if (!errormsg.Nil() && (int32(errormsg.Get()) != NUL)) && (did_emsg == 0) {
		if ((sourcing != 0) || (KeyTyped == 0)) && !did_append_cmd {
			if errormsg != IObuff {
				musl_strcpy(IObuff, errormsg)
				errormsg = IObuff
			}
			append_command((*cmdlinep))
		}
		emsg(errormsg)
	}
	undo_cmdmod(&cmdmod)
	cmdmod = save_cmdmod
	reg_executing = save_reg_executing
	pending_end_reg_executing = save_pending_end_reg_executing
	if !ea.nextcmd.Nil() && (int32(ea.nextcmd.Get()) == NUL) {
		ea.nextcmd = Ptr[byte]{}
	}
	return ea.nextcmd
}

