func do_sleep(msec int64, hide_cursor int32) {
	var done int64 = 0
	var wait_now int64
	var start_tv int64 = musl_now_ms()
	if hide_cursor != 0 {
		cursor_sleep()
	} else {
		cursor_on()
	}
	out_flush_cursor(FALSE, FALSE)
	for (got_int == 0) && (done < msec) {
		var t1 int64
		if (msec - done) > 1000 {
			t1 = 1000
		} else {
			t1 = msec - done
		}
		wait_now = t1
		ui_delay(wait_now, TRUE)
		ui_breakcheck()
		done = musl_now_ms() - start_tv
	}
	if got_int != 0 {
		vpeekc()
	}
	if hide_cursor != 0 {
		cursor_unsleep()
	}
}

func ex_winsize(eap *S_exarg) {
	var w int32
	var h int32
	arg := eap.arg
	var p Ptr[byte]
	if !musl_isdigit(int32(arg.Get())) {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), arg)
		emsg(iobuff_or(gettext_(e_invalid_argument_str)))
		return
	}
	w = int32(getdigits(Addr(&arg)))
	arg = skipwhite(arg)
	p = arg
	h = int32(getdigits(Addr(&arg)))
	if (int32(p.Get()) != NUL) && (int32(arg.Get()) == NUL) {
		set_shellsize(w, h, TRUE)
	} else {
		emsg(gettext_(e_winsize_requires_two_number_arguments))
	}
}

func ex_operators(eap *S_exarg) {
	var oa S_oparg_S
	clear_oparg(&oa)
	oa.regname = eap.regname
	oa.start.lnum = eap.line1
	oa.end.lnum = eap.line2
	oa.line_count = (eap.line2 - eap.line1) + 1
	oa.motion_type = MLINE
	virtual_op = FALSE
	if eap.cmdidx != CMD_yank {
		setpcmark()
		curwin.w_cursor.lnum = eap.line1
		beginline(BL_SOL | BL_FIX)
	}
	if VIsual_active != 0 {
		end_visual_mode()
	}
	switch eap.cmdidx {
	case CMD_delete:
		oa.op_type = OP_DELETE
		op_delete(&oa)
	case CMD_yank:
		oa.op_type = OP_YANK
		op_yank(&oa, FALSE, TRUE)
	default:
		if eap.cmdidx == CMD_rshift {
			oa.op_type = OP_RSHIFT
		} else {
			oa.op_type = OP_LSHIFT
		}
		op_shift(&oa, FALSE, eap.amount)
	}
	virtual_op = MAYBE
	ex_may_print(eap)
}

