func ex_copymove(eap *S_exarg) {
	var n int64 = get_address(eap, &eap.arg, eap.addr_type, FALSE, FALSE, FALSE, 1)
	if eap.arg.Nil() {
		eap.nextcmd = Ptr[byte]{}
		return
	}
	get_flags(eap)
	if ((n == LONG_MAX) || (n < 0)) || (n > curbuf.b_ml.ml_line_count) {
		emsg(gettext_(e_invalid_range))
		return
	}
	if eap.cmdidx == CMD_move {
		if !do_move(eap.line1, eap.line2, n) {
			return
		}
	} else {
		ex_copy(eap.line1, eap.line2, n)
	}
	u_clearline()
	beginline(BL_SOL | BL_FIX)
	ex_may_print(eap)
}

func ex_may_print(eap *S_exarg) {
	if eap.flags != 0 {
		print_line(curwin.w_cursor.lnum, (eap.flags & EXFLAG_NR), (eap.flags & EXFLAG_LIST))
	}
}

func ex_submagic(eap *S_exarg) {
	saved := magic_overruled
	var t1 optmagic_T
	if eap.cmdidx == CMD_smagic {
		t1 = OPTION_MAGIC_ON
	} else {
		t1 = OPTION_MAGIC_OFF
	}
	magic_overruled = t1
	ex_substitute(eap)
	magic_overruled = saved
}

func ex_join(eap *S_exarg) {
	curwin.w_cursor.lnum = eap.line1
	if eap.line1 == eap.line2 {
		if eap.addr_count >= 2 {
			return
		}
		if eap.line2 == curbuf.b_ml.ml_line_count {
			beep_flush()
			return
		}
		eap.line2++
	}
	do_join((eap.line2-eap.line1)+1, B2i(eap.forceit == 0), TRUE, TRUE, TRUE)
	beginline(BL_WHITE | BL_FIX)
	ex_may_print(eap)
}

func ex_at(eap *S_exarg) {
	var c int32
	prev_len := typebuf.tb_len
	curwin.w_cursor.lnum = eap.line2
	check_cursor_col()
	c = int32(eap.arg.Get())
	if (c == NUL) || ((c == '*') && (int32(eap.cmd.Get()) == '*')) {
		c = '@'
	}
	if !do_execreg(c, TRUE, B2i(!vim_strchr(p_cpo, CPO_EXECBUF).Nil()), TRUE) {
		beep_flush()
		return
	}
	save_efr := exec_from_reg
	exec_from_reg = TRUE
	for !stuff_empty() || (typebuf.tb_len > prev_len) {
		do_cmdline(Ptr[byte]{}, getexline, (DOCMD_NOWAIT|DOCMD_VERBOSE)|DOCMD_GETEXLINE)
	}
	exec_from_reg = save_efr
}

func ex_undo(eap *S_exarg) {
	if eap.addr_count == 1 {
		undo_time(eap.line2, FALSE, FALSE, TRUE)
	} else {
		u_undo(1)
	}
}

func ex_redo(eap *S_exarg) {
	u_redo(1)
}

func ex_later(eap *S_exarg) {
	var count int64 = 0
	var sec bool = false
	var file bool = false
	p := eap.arg
	if int32(p.Get()) == NUL {
		count = 1
	} else if musl_isdigit(int32(p.Get())) {
		count = getdigits(Addr(&p))
		switch p.Get() {
		case 's':
			p = p.Add(1)
			sec = true
		case 'm':
			p = p.Add(1)
			sec = true
			count *= 60
		case 'h':
			p = p.Add(1)
			sec = true
			count *= 60 * 60
		case 'd':
			p = p.Add(1)
			sec = true
			count *= (24 * 60) * 60
		case 'f':
			p = p.Add(1)
			file = true
		}
	}
	if int32(p.Get()) != NUL {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), eap.arg)
		emsg(iobuff_or(gettext_(e_invalid_argument_str)))
	} else {
		var t1 int64
		if eap.cmdidx == CMD_earlier {
			t1 = -count
		} else {
			t1 = count
		}
		undo_time(t1, B2i(sec), B2i(file), FALSE)
	}
}

func ex_redraw(eap *S_exarg) {
	redraw_cmd(eap.forceit)
}

func redraw_cmd(clear_ int32) {
	save_RedrawingDisabled := RedrawingDisabled
	RedrawingDisabled = 0
	save_p_lz := p_lz
	p_lz = FALSE
	validate_cursor()
	update_topline()
	var t2 int32
	if clear_ != 0 {
		t2 = UPD_CLEAR
	} else {
		var t1 int32
		if VIsual_active != 0 {
			t1 = UPD_INVERTED
		} else {
			t1 = 0
		}
		t2 = t1
	}
	update_screen(t2)
	if (State & MODE_CMDLINE) == 0 {
		setcursor()
	}
	RedrawingDisabled = save_RedrawingDisabled
	p_lz = save_p_lz
	screen_stop_highlight()
	msg_didout = FALSE
	msg_col = 0
	need_wait_return = FALSE
	if State&MODE_CMDLINE != 0 {
		redrawcmdline()
	}
	out_flush()
}

func ex_redrawstatus(eap *S_exarg) {
	if eap.forceit != 0 {
		status_redraw_all()
	} else {
		status_redraw_curbuf()
	}
	redraw_vseps = TRUE
	if (msg_scrolled != 0) && ((State & MODE_CMDLINE) != 0) {
		return
	}
	save_RedrawingDisabled := RedrawingDisabled
	RedrawingDisabled = 0
	save_p_lz := p_lz
	p_lz = FALSE
	if State&MODE_CMDLINE != 0 {
		redraw_statuslines()
	} else {
		var t1 int32
		if VIsual_active != 0 {
			t1 = UPD_INVERTED
		} else {
			t1 = 0
		}
		update_screen(t1)
	}
	RedrawingDisabled = save_RedrawingDisabled
	p_lz = save_p_lz
	out_flush()
}

func ex_mark(eap *S_exarg) {
	var pos pos_T
	if int32(eap.arg.Get()) == NUL {
		emsg(gettext_(e_argument_required))
		return
	}
	if int32(eap.arg.At(1)) != NUL {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_trailing_characters_str), eap.arg)
		emsg(iobuff_or(gettext_(e_trailing_characters_str)))
		return
	}
	pos = curwin.w_cursor
	curwin.w_cursor.lnum = eap.line2
	beginline(BL_WHITE | BL_FIX)
	if setmark(int32(eap.arg.Get())) == FAIL {
		emsg(gettext_(e_argument_must_be_letter_or_forward_backward_quote))
	}
	curwin.w_cursor = pos
}

