func put_on_cmdline(str Ptr[byte], len_ int32, redraw int32) bool {
	var retval bool
	var i int32
	var m int32
	var c int32
	if len_ < 0 {
		len_ = int32(musl_strlen(str))
	}
	if ((ccline.cmdlen + len_) + 1) >= ccline.cmdbufflen {
		retval = (realloc_cmdbuff((ccline.cmdlen + len_) + 1))
	} else {
		retval = true
	}
	if B2i(retval) == OK {
		if ccline.overstrike == 0 {
			Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos)).Add(int(len_)), ccline.cmdbuff.Add(int(ccline.cmdpos)), int(uint64((ccline.cmdlen - ccline.cmdpos))))
			ccline.cmdlen += len_
		} else {
			m = 0
			i = 0
			for ; i < len_; i += utfc_ptr2len(str.Add(int(i))) {
				m++
			}
			i = ccline.cmdpos
			for ; (i < ccline.cmdlen) && (m > 0); i += utfc_ptr2len(ccline.cmdbuff.Add(int(i))) {
				m--
			}
			if i < ccline.cmdlen {
				Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos)).Add(int(len_)), ccline.cmdbuff.Add(int(i)), int(uint64((ccline.cmdlen - i))))
				ccline.cmdlen += (ccline.cmdpos + len_) - i
			} else {
				ccline.cmdlen = ccline.cmdpos + len_
			}
		}
		Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos)), str, int(uint64(len_)))
		ccline.cmdbuff.Set(int(ccline.cmdlen), NUL)
		i = 0
		c = utf_ptr2char(ccline.cmdbuff.Add(int(ccline.cmdpos)))
		for (ccline.cmdpos > 0) && utf_iscomposing(c) {
			i = utf_head_off(ccline.cmdbuff, ccline.cmdbuff.Add(int(ccline.cmdpos)).Add(-1)) + 1
			ccline.cmdpos -= i
			len_ += i
			c = utf_ptr2char(ccline.cmdbuff.Add(int(ccline.cmdpos)))
		}
		if i != 0 {
			i = ptr2cells(ccline.cmdbuff.Add(int(ccline.cmdpos)))
			ccline.cmdspos -= i
			msg_col -= i
			if msg_col < 0 {
				msg_col += cmdline_width
				msg_row--
			}
		}
		if (redraw != 0) && (cmd_silent == 0) {
			msg_no_more = TRUE
			i = cmdline_row
			cursorcmd()
			draw_cmdline(ccline.cmdpos, ccline.cmdlen-ccline.cmdpos)
			if (cmdline_row != i) || (ccline.overstrike != 0) {
				msg_clr_eos()
			}
			msg_no_more = FALSE
		}
		if KeyTyped != 0 {
			m = int32(int64(cmdline_width) * Rows)
			if m < 0 {
				m = MAXCOL
			}
		} else {
			m = MAXCOL
		}
		i = 0
		for ; i < len_; i++ {
			c = cmdline_charsize(ccline.cmdpos)
			correct_cmdspos(ccline.cmdpos, c)
			if (ccline.cmdspos + c) < m {
				ccline.cmdspos += c
			}
			c = utfc_ptr2len(ccline.cmdbuff.Add(int(ccline.cmdpos))) - 1
			if c > ((len_ - i) - 1) {
				c = (len_ - i) - 1
			}
			ccline.cmdpos += c
			i += c
			ccline.cmdpos++
		}
	}
	if redraw != 0 {
		msg_check()
	}
	return (retval)
}

