func cmdline_paste(regname int32, literally int32, remcr int32) bool {
	var i int64
	var arg Ptr[byte]
	var p Ptr[byte]
	var allocated int32
	if (((((regname != Ctrl_F) && (regname != Ctrl_P)) && (regname != Ctrl_W)) && (regname != Ctrl_A)) && (regname != Ctrl_L)) && !valid_yank_reg(regname, FALSE) {
		return false
	}
	line_breakcheck()
	if got_int != 0 {
		return false
	}
	textlock++
	i = int64(B2i(get_spec_reg(regname, &arg, &allocated, TRUE)))
	textlock--
	if i != 0 {
		if arg.Nil() {
			return false
		}
		p = arg
		if (p_is != 0) && (regname == Ctrl_W) {
			var w Ptr[byte]
			var len_ int32
			w = ccline.cmdbuff.Add(int(ccline.cmdpos))
			for w.Gt(ccline.cmdbuff) {
				len_ = utf_head_off(ccline.cmdbuff, w.Add(-1)) + 1
				if !vim_iswordc(utf_ptr2char(w.Add(-int(len_)))) {
					break
				}
				w = w.Add(-int(len_))
			}
			len_ = int32(int64(ccline.cmdbuff.Add(int(ccline.cmdpos)).Sub(w)))
			var t1 bool
			if p_ic != 0 {
				t1 = musl_strncasecmp(w, arg, usize(len_)) == 0
			} else {
				t1 = musl_strncmp(w, arg, usize(len_)) == 0
			}
			if t1 {
				p = p.Add(int(len_))
			}
		}
		cmdline_paste_str(p, literally)
		return true
	}
	return (cmdline_paste_reg(regname, literally, remcr))
}

func cmdline_paste_str(s Ptr[byte], literally int32) {
	var c int32
	var cv int32
	if literally != 0 {
		put_on_cmdline(s, -1, TRUE)
	} else {
		for int32(s.Get()) != NUL {
			cv = int32(s.Get())
			if (cv == Ctrl_V) && (s.At(1) != 0) {
				s = s.Add(1)
			}
			c = mb_cptr2char_adv(&s)
			if (((((((cv == Ctrl_V) || (c == ESC)) || (c == Ctrl_C)) || (c == CAR)) || (c == NL)) || (c == Ctrl_L)) || (c == intr_char)) || ((c == Ctrl_BSL) && (int32(s.Get()) == Ctrl_N)) {
				stuffcharReadbuff(Ctrl_V)
			}
			stuffcharReadbuff(c)
		}
	}
}

