func get_list_range(str *Ptr[byte], num1 *int32, num2 *int32) bool {
	var len_ int32
	var first bool = false
	var num varnumber_T
	*str = skipwhite((*str))
	if (int32((*str).Get()) == '-') || vim_isdigit(int32((*str).Get())) {
		vim_str2nr((*str), nil, &len_, 0, &num, nil, 0, FALSE, nil)
		*str = (*str).Add(int(len_))
		if num > INT_MAX {
			return false
		}
		*num1 = int32(num)
		first = true
	}
	*str = skipwhite((*str))
	if int32((*str).Get()) == ',' {
		*str = skipwhite((*str).Add(1))
		vim_str2nr((*str), nil, &len_, 0, &num, nil, 0, FALSE, nil)
		if len_ > 0 {
			*str = skipwhite((*str).Add(int(len_)))
			if num > INT_MAX {
				return false
			}
			*num2 = int32(num)
		} else if !first {
			return false
		}
	} else if first {
		*num2 = (*num1)
	}
	return true
}

