func shorten_dir_len(str Ptr[byte], trim_len int32) {
	var tail Ptr[byte]
	var s Ptr[byte]
	var d Ptr[byte]
	var skip bool = false
	var dirchunk_len int32 = 0
	tail = gettail(str)
	d = str
	s = str
	for ; ; s = s.Add(1) {
		if s.Ge(tail) {
			var t1 Ptr[byte] = d
			d = d.Add(1)
			t1.Put(s.Get())
			if int32(s.Get()) == NUL {
				break
			}
		} else if vim_ispathsep(int32(s.Get())) {
			var t2 Ptr[byte] = d
			d = d.Add(1)
			t2.Put(s.Get())
			skip = false
			dirchunk_len = 0
		} else if !skip {
			var t3 Ptr[byte] = d
			d = d.Add(1)
			t3.Put(s.Get())
			if (int32(s.Get()) != '~') && (int32(s.Get()) != '.') {
				dirchunk_len++
				if dirchunk_len >= trim_len {
					skip = true
				}
			}
			l := utfc_ptr2len(s)
			for {
				l--
				if !(l > 0) {
					break
				}
				var t4 Ptr[byte] = d
				d = d.Add(1)
				s = s.Add(1)
				t4.Put(s.Get())
			}
		}
	}
}

