func file_name_in_line(line Ptr[byte], col int32, options int32, count int64, rel_fname Ptr[byte], file_lnum *linenr_T) Ptr[byte] {
	var ptr Ptr[byte]
	var len_ int32
	var in_type bool = true
	var is_url bool = false
	ptr = line.Add(int(col))
	for (int32(ptr.Get()) != NUL) && !vim_isfilec(int32(ptr.Get())) {
		ptr = ptr.Add(int(utfc_ptr2len(ptr)))
	}
	if int32(ptr.Get()) == NUL {
		if options&FNAME_MESS != 0 {
			emsg(gettext_(e_no_file_name_under_cursor))
		}
		return Ptr[byte]{}
	}
	for ptr.Gt(line) {
		len_ = utf_head_off(line, ptr.Add(-1))
		if len_ > 0 {
			ptr = ptr.Add(-int(len_ + 1))
		} else if vim_isfilec(int32(ptr.At(-1))) || (((options & FNAME_HYP) != 0) && (path_is_url(ptr.Add(-1)) != 0)) {
			ptr = ptr.Add(-1)
		} else {
			break
		}
	}
	len_ = 0
	for ((vim_isfilec(int32(ptr.At(int(len_)))) || ((int32(ptr.At(int(len_))) == 92) && (int32(ptr.At(int(len_+1))) == (' ')))) || (((options & FNAME_HYP) != 0) && (path_is_url(ptr.Add(int(len_))) != 0))) || (is_url && !vim_strchr(S(":?&="), int32(ptr.At(int(len_)))).Nil()) {
		if ((int32(ptr.At(int(len_))) >= 'A') && (int32(ptr.At(int(len_))) <= 'Z')) || ((int32(ptr.At(int(len_))) >= 'a') && (int32(ptr.At(int(len_))) <= 'z')) {
			if in_type && (path_is_url(ptr.Add(int(len_)).Add(1)) != 0) {
				is_url = true
			}
		} else {
			in_type = false
		}
		if int32(ptr.At(int(len_))) == 92 {
			len_++
		}
		len_ += utfc_ptr2len(ptr.Add(int(len_)))
	}
	if ((len_ > 2) && !vim_strchr(S(".,:;!"), int32(ptr.At(int(len_-1)))).Nil()) && (int32(ptr.At(int(len_-2))) != '.') {
		len_--
	}
	if file_lnum != nil {
		var p Ptr[byte]
		match_text := S(" line ")
		var match_textlen usize = 6
		p = ptr.Add(int(len_))
		if musl_strncmp(p, match_text, match_textlen) == 0 {
			p = p.Add(int(match_textlen))
		} else {
			match_text = gettext_(line_msg)
			match_textlen = musl_strlen(match_text)
			if musl_strncmp(p, match_text, match_textlen) == 0 {
				p = p.Add(int(match_textlen))
			} else {
				p = skipwhite(p)
			}
		}
		if int32(p.Get()) != NUL {
			if !musl_isdigit(int32(p.Get())) {
				p = p.Add(1)
			}
			p = skipwhite(p)
			if musl_isdigit(int32(p.Get())) {
				*file_lnum = int64(int32(getdigits(Addr(&p))))
			}
		}
	}
	return find_file_name_in_path(ptr, len_, options, count, rel_fname)
}

func find_file_name_in_path(ptr Ptr[byte], len_ int32, options int32, count int64, rel_fname Ptr[byte]) Ptr[byte] {
	var file_name Ptr[byte]
	if len_ == 0 {
		return Ptr[byte]{}
	}
	file_name = vim_strnsave(ptr, usize(len_))
	return file_name
}

