func getcmdkeycmd(promptc int32, indent int32, do_concat getline_opt_T) Ptr[byte] {
	var line_ga S_growarray
	var c1 int32 = -1
	var c2 int32
	var cmod int32 = 0
	var aborted bool = false
	ga_init2(&line_ga, 1, 32)
	no_mapping++
	got_int = FALSE
	for (c1 != NUL) && !aborted {
		if !ga_grow(&line_ga, 32) {
			aborted = true
			break
		}
		if vgetorpeek(FALSE) == NUL {
			emsg(gettext_(e_cmd_mapping_must_end_with_cr))
			aborted = true
			break
		}
		c1 = vgetorpeek(TRUE)
		if c1 == 0x80 {
			c1 = vgetorpeek(TRUE)
			c2 = vgetorpeek(TRUE)
			if c1 == KS_MODIFIER {
				cmod = c2
				continue
			}
			var t2 int32
			if c1 == KS_SPECIAL {
				t2 = 0x80
			} else {
				var t1 int32
				if c1 == KS_ZERO {
					t1 = -(KS_ZERO + (88 << 8))
				} else {
					t1 = -(c1 + (c2 << 8))
				}
				t2 = t1
			}
			c1 = t2
			if c1 == K_ESC {
				c1 = ESC
			}
		}
		if got_int != 0 {
			aborted = true
		} else if (c1 == 13) || (c1 == 10) {
			c1 = NUL
		} else if c1 == ESC {
			aborted = true
		} else if (c1 == K_COMMAND) || (c1 == K_SCRIPT_COMMAND) {
			emsg(gettext_(e_cmd_mapping_must_end_with_cr_before_second_cmd))
			aborted = true
		} else if c1 == K_SNR {
			ga_concat_len(&line_ga, S("<SNR>"), 5)
		} else {
			if cmod != 0 {
				ga_append(&line_ga, 0x80)
				ga_append(&line_ga, KS_MODIFIER)
				ga_append(&line_ga, cmod)
			}
			if c1 < 0 {
				ga_append(&line_ga, 0x80)
				var t4 int32
				if c1 == 0x80 {
					t4 = KS_SPECIAL
				} else {
					var t3 int32
					if c1 == NUL {
						t3 = KS_ZERO
					} else {
						t3 = (-c1 & 0xff)
					}
					t4 = t3
				}
				ga_append(&line_ga, t4)
				var t5 int32
				if (c1 == 0x80) || (c1 == NUL) {
					t5 = 'X'
				} else {
					t5 = int32(((uint32(-c1) >> 8) & 0xff))
				}
				ga_append(&line_ga, t5)
			} else {
				ga_append(&line_ga, c1)
			}
		}
		cmod = 0
	}
	no_mapping--
	if aborted {
		ga_clear(&line_ga)
	}
	return GaData[byte](&line_ga)
}

