func cterm_idx_to_rgb(idx int32, r *int32, g *int32, b *int32) {
	if (idx < 0) || (idx > 255) {
		*b = 0
		*g = (*b)
		*r = (*g)
		return
	}
	if idx < 16 {
		rgb := cterm_color_16[int(idx)]
		*r = int32((rgb >> 16) & 0xFF)
		*g = int32((rgb >> 8) & 0xFF)
		*b = int32(rgb & 0xFF)
	} else if idx < 232 {
		n := idx - 16
		*r = cterm_idx_to_rgb_cube[int((n/36)%6)]
		*g = cterm_idx_to_rgb_cube[int((n/6)%6)]
		*b = cterm_idx_to_rgb_cube[int(n%6)]
	} else {
		v := 8 + ((idx - 232) * 10)
		*b = v
		*g = (*b)
		*r = (*g)
	}
}

func rgb_to_cterm_idx(r int32, g int32, b int32) int32 {
	var best int32 = 0
	var best_d int64 = -1
	var i int32 = 16
	for ; i < 232; i++ {
		n := i - 16
		cr := rgb_to_cterm_idx_cube[int((n/36)%6)]
		cg := rgb_to_cterm_idx_cube[int((n/6)%6)]
		cb := rgb_to_cterm_idx_cube[int(n%6)]
		var d int64 = int64((((cr - r) * (cr - r)) + ((cg - g) * (cg - g))) + ((cb - b) * (cb - b)))
		if (best_d < 0) || (d < best_d) {
			best_d = d
			best = i
		}
	}
	i = 232
	for ; i < 256; i++ {
		v := 8 + ((i - 232) * 10)
		var d_2 int64 = int64((((v - r) * (v - r)) + ((v - g) * (v - g))) + ((v - b) * (v - b)))
		if d_2 < best_d {
			best_d = d_2
			best = i
		}
	}
	return best
}

func resolve_color_to_rgb(cterm_c int32, rgb int64, r *int32, g *int32, b *int32) bool {
	if cterm_c > 0 {
		cterm_idx_to_rgb(cterm_c-1, r, g, b)
		return true
	}
	return false
}

func resolve_fallback_color(cterm_c int32, rgb int64, default_rgb int64) int64 {
	var red int32
	var green int32
	var blue int32
	if !resolve_color_to_rgb(cterm_c, rgb, &red, &green, &blue) {
		return default_rgb
	} else {
		return int64(((red << 16) | (green << 8)) | blue)
	}
}

func resolve_fallback_fg_to_rgb() {
	var fgcolor_or_gui_fgcolor int64 = 33554431
	var t1 int64
	if int32(p_bg.Get()) == 'l' {
		t1 = 0x000000
	} else {
		t1 = 0xFFFFFF
	}
	fallback_fg_rgb = resolve_fallback_color(cterm_normal_fg_color, fgcolor_or_gui_fgcolor, t1)
}

func resolve_fallback_bg_to_rgb() {
	var bgcolor_or_gui_bgcolor int64 = 33554431
	var t1 int64
	if int32(p_bg.Get()) == 'l' {
		t1 = 0xFFFFFF
	} else {
		t1 = 0x000000
	}
	fallback_bg_rgb = resolve_fallback_color(cterm_normal_bg_color, bgcolor_or_gui_bgcolor, t1)
}

func blend_cterm_colors(popup_c int32, popup_rgb int64, under_c int32, under_rgb int64, default_rgb int32, blend_val int32) int32 {
	var pr int32
	var pg int32
	var pb int32
	var ur int32
	var ug int32
	var ub int32
	var r int32
	var g int32
	var b int32
	if t_colors < 256 {
		return popup_c
	}
	if !resolve_color_to_rgb(popup_c, popup_rgb, &pr, &pg, &pb) {
		return under_c
	}
	if blend_val <= 0 {
		return rgb_to_cterm_idx(pr, pg, pb) + 1
	}
	if !resolve_color_to_rgb(under_c, under_rgb, &ur, &ug, &ub) {
		ur = (default_rgb >> 16) & 0xFF
		ug = (default_rgb >> 8) & 0xFF
		ub = default_rgb & 0xFF
	}
	if blend_val >= 100 {
		return rgb_to_cterm_idx(ur, ug, ub) + 1
	}
	r = pr + (((ur - pr) * blend_val) / 100)
	g = pg + (((ug - pg) * blend_val) / 100)
	b = pb + (((ub - pb) * blend_val) / 100)
	return rgb_to_cterm_idx(r, g, b) + 1
}

