func highlight_arg_to_string(type_ int32, iarg int32, sarg Ptr[byte], buf Ptr[byte]) Ptr[byte] {
	if type_ == LIST_INT {
		vim_snprintf(buf, MAX_ATTR_LEN, S("%d"), iarg-1)
	} else if type_ == LIST_STRING {
		return sarg
	} else {
		var buflen usize
		buf.Set(0, NUL)
		buflen = 0
		var i int32 = 0
		for ; i < 13; i++ {
			if iarg&highlight_index_tab[int(i)].key != 0 {
				if buflen > 0 {
					musl_strcpy(buf.Add(int(buflen)), S(","))
					buflen++
				}
				musl_strcpy(buf.Add(int(buflen)), highlight_index_tab[int(i)].value.string_)
				buflen += highlight_index_tab[int(i)].value.length
				iarg &= ^highlight_index_tab[int(i)].key
			}
		}
	}
	return buf
}

func highlight_list_arg(id int32, didh int32, type_ int32, iarg int32, sarg Ptr[byte], name Ptr[byte]) int32 {
	var buf Ptr[byte] = Mk[byte](120)
	var ts Ptr[byte]
	if got_int != 0 {
		return FALSE
	}
	var t1 bool
	if type_ == LIST_STRING {
		t1 = sarg.Nil()
	} else {
		t1 = (iarg == 0)
	}
	if t1 {
		return didh
	}
	ts = highlight_arg_to_string(type_, iarg, sarg, buf)
	syn_list_header(didh, int32(((uint64(vim_strsize(ts)) + musl_strlen(name)) + 1)), id)
	didh = TRUE
	if got_int == 0 {
		if int32(name.Get()) != NUL {
			msg_puts_attr(name, highlight_attr[3])
			msg_puts_attr(S("="), highlight_attr[3])
		}
		msg_outtrans(ts)
	}
	return didh
}

func syn_list_header(did_header int32, outlen int32, id int32) bool {
	var endcol int32 = 19
	var newline bool = true
	var name_col int32 = 0
	if did_header == 0 {
		msg_putchar(10)
		if got_int != 0 {
			return true
		}
		msg_outtrans(GaData[hl_group_T](&highlight_ga).Ref(int(id - 1)).sg_name)
		name_col = msg_col
		endcol = 15
	} else if ((msg_col + outlen) + 1) >= cmdline_width {
		msg_putchar(10)
		if got_int != 0 {
			return true
		}
	} else {
		if msg_col >= endcol {
			newline = false
		}
	}
	if msg_col >= endcol {
		endcol = msg_col + 1
	}
	if cmdline_width <= endcol {
		endcol = cmdline_width - 1
	}
	msg_advance(endcol)
	if did_header == 0 {
		if (endcol == (cmdline_width - 1)) && (endcol <= name_col) {
			msg_putchar(' ')
		}
		msg_puts_attr(S("xxx"), syn_id2attr(id))
		msg_putchar(' ')
	}
	return (newline)
}

func set_hl_attr(idx int32) {
	var at_en S_attr_entry
	sgp := GaData[hl_group_T](&highlight_ga).Add(int(idx))
	if !sgp.P().sg_name_u.Nil() && (musl_strcmp(sgp.P().sg_name_u, S("NORMAL")) == 0) {
		return
	}
	if sgp.P().sg_start.Nil() && sgp.P().sg_stop.Nil() {
		sgp.P().sg_term_attr = sgp.P().sg_term
	} else {
		at_en.ae_attr = int16(sgp.P().sg_term)
		at_en.ae_u.term.start = sgp.P().sg_start
		at_en.ae_u.term.stop = sgp.P().sg_stop
		sgp.P().sg_term_attr = get_attr_entry(&term_attr_table, &at_en)
	}
	if (((sgp.P().sg_cterm_fg == 0) && (sgp.P().sg_cterm_bg == 0)) && (sgp.P().sg_cterm_ul == 0)) && (sgp.P().sg_cterm_font == 0) {
		sgp.P().sg_cterm_attr = sgp.P().sg_cterm
	} else {
		at_en.ae_attr = int16(sgp.P().sg_cterm)
		at_en.ae_u.cterm.fg_color = short_u(sgp.P().sg_cterm_fg)
		at_en.ae_u.cterm.bg_color = short_u(sgp.P().sg_cterm_bg)
		at_en.ae_u.cterm.ul_color = short_u(sgp.P().sg_cterm_ul)
		at_en.ae_u.cterm.font = short_u(sgp.P().sg_cterm_font)
		sgp.P().sg_cterm_attr = get_attr_entry(&cterm_attr_table, &at_en)
	}
}

