func change_indent(type_ int32, amount int32, round int32, replaced int32, call_changed_bytes int32) {
	var vcol int32
	var last_vcol int32
	var insstart_less int32
	var new_cursor_col int32
	var i int32
	var ptr Ptr[byte]
	var save_p_list int32
	var start_col int32
	var vc colnr_T
	var orig_col colnr_T = 0
	var new_line Ptr[byte]
	var orig_line Ptr[byte] = Ptr[byte]{}
	if State&VREPLACE_FLAG != 0 {
		len_ := ml_get_curline_len()
		orig_line = vim_strnsave(ml_get_curline(), usize(len_))
		orig_col = curwin.w_cursor.col
	}
	save_p_list = curwin.w_onebuf_opt.wo_list
	curwin.w_onebuf_opt.wo_list = FALSE
	vc = getvcol_nolist(&curwin.w_cursor)
	vcol = vc
	start_col = curwin.w_cursor.col
	new_cursor_col = curwin.w_cursor.col
	beginline(BL_WHITE)
	new_cursor_col -= curwin.w_cursor.col
	insstart_less = curwin.w_cursor.col
	if new_cursor_col < 0 {
		vcol = get_indent() - vcol
	}
	if new_cursor_col > 0 {
		start_col = -1
	}
	if type_ == INDENT_SET {
		var t1 int32
		if call_changed_bytes != 0 {
			t1 = SIN_CHANGED
		} else {
			t1 = 0
		}
		set_indent(amount, t1)
	} else {
		save_State := State
		if State&VREPLACE_FLAG != 0 {
			State = MODE_INSERT
		}
		shift_line(B2i(type_ == INDENT_DEC), round, 1, call_changed_bytes)
		State = save_State
	}
	insstart_less -= curwin.w_cursor.col
	if new_cursor_col >= 0 {
		if new_cursor_col == 0 {
			insstart_less = MAXCOL
		}
		new_cursor_col += curwin.w_cursor.col
	} else if (State & MODE_INSERT) == 0 {
		new_cursor_col = curwin.w_cursor.col
	} else {
		var cts chartabsize_T
		vcol = get_indent() - vcol
		var t2 int32
		if vcol < 0 {
			t2 = 0
		} else {
			t2 = vcol
		}
		curwin.w_virtcol = t2
		last_vcol = 0
		ptr = ml_get_curline()
		init_chartabsize_arg(&cts, curwin, 0, 0, ptr, ptr)
		for cts.cts_vcol <= curwin.w_virtcol {
			last_vcol = cts.cts_vcol
			if cts.cts_vcol > 0 {
				cts.cts_ptr = cts.cts_ptr.Add(int(utfc_ptr2len(cts.cts_ptr)))
			}
			if int32(cts.cts_ptr.Get()) == NUL {
				break
			}
			cts.cts_vcol += lbr_chartabsize(&cts)
		}
		vcol = last_vcol
		new_cursor_col = int32(int64(cts.cts_ptr.Sub(cts.cts_line)))
		if vcol != curwin.w_virtcol {
			curwin.w_cursor.col = new_cursor_col
			i = curwin.w_virtcol - vcol
			ptr = Alloc(int(i + 1))
			var ptrlen usize
			new_cursor_col += i
			ptr.Set(int(i), NUL)
			ptrlen = usize(i)
			for {
				i--
				if !(i >= 0) {
					break
				}
				ptr.Set(int(i), ' ')
			}
			ins_str(ptr, ptrlen)
		}
		insstart_less = MAXCOL
	}
	curwin.w_onebuf_opt.wo_list = save_p_list
	if new_cursor_col <= 0 {
		curwin.w_cursor.col = 0
	} else {
		curwin.w_cursor.col = new_cursor_col
	}
	curwin.w_set_curswant = true
	changed_cline_bef_curs()
	if State&MODE_INSERT != 0 {
		if (curwin.w_cursor.lnum == Insstart.lnum) && (Insstart.col != 0) {
			if Insstart.col <= insstart_less {
				Insstart.col = 0
			} else {
				Insstart.col -= insstart_less
			}
		}
		if ai_col <= insstart_less {
			ai_col = 0
		} else {
			ai_col -= insstart_less
		}
	}
	if (((State & REPLACE_FLAG) != 0) && ((State & VREPLACE_FLAG) == 0)) && (start_col >= 0) {
		for start_col > curwin.w_cursor.col {
			replace_join(0)
			start_col--
		}
		for (start_col < curwin.w_cursor.col) || (replaced != 0) {
			replace_push(NUL)
			if replaced != 0 {
				replace_push(replaced)
				replaced = NUL
			}
			start_col++
		}
	}
	if State&VREPLACE_FLAG != 0 {
		if orig_line.Nil() {
			return
		}
		len__2 := ml_get_curline_len()
		new_line = vim_strnsave(ml_get_curline(), usize(len__2))
		new_line.Set(int(curwin.w_cursor.col), NUL)
		ml_replace(curwin.w_cursor.lnum, orig_line, FALSE)
		curwin.w_cursor.col = orig_col
		backspace_until_column(0)
		ins_bytes(new_line)
	}
}

func copy_indent(size int32, src Ptr[byte]) bool {
	var p Ptr[byte] = Ptr[byte]{}
	var line Ptr[byte] = Ptr[byte]{}
	var s Ptr[byte]
	var todo int32
	var ind_len int32
	var line_len int32 = 0
	var tab_pad int32
	var ind_done int32
	var round int32 = 1
	for ; round <= 2; round++ {
		todo = size
		ind_len = 0
		ind_done = 0
		s = src
		for (todo > 0) && ((int32(s.Get()) == (' ')) || (int32(s.Get()) == 9)) {
			if int32(s.Get()) == TAB {
				tab_pad = int32(curbuf.b_p_ts) - (ind_done % int32(curbuf.b_p_ts))
				if todo < tab_pad {
					break
				}
				todo -= tab_pad
				ind_done += tab_pad
			} else {
				todo--
				ind_done++
			}
			ind_len++
			if !p.Nil() {
				var t1 Ptr[byte] = p
				p = p.Add(1)
				t1.Put(s.Get())
			}
			s = s.Add(1)
		}
		tab_pad = int32(curbuf.b_p_ts) - (ind_done % int32(curbuf.b_p_ts))
		if (todo >= tab_pad) && (curbuf.b_p_et == 0) {
			todo -= tab_pad
			ind_len++
			if !p.Nil() {
				var t2 Ptr[byte] = p
				p = p.Add(1)
				t2.Put(TAB)
			}
		}
		if curbuf.b_p_et == 0 {
			for todo >= int32(curbuf.b_p_ts) {
				todo -= int32(curbuf.b_p_ts)
				ind_len++
				if !p.Nil() {
					var t3 Ptr[byte] = p
					p = p.Add(1)
					t3.Put(TAB)
				}
			}
		}
		for todo > 0 {
			todo--
			ind_len++
			if !p.Nil() {
				var t4 Ptr[byte] = p
				p = p.Add(1)
				t4.Put(' ')
			}
		}
		if p.Nil() {
			line_len = ml_get_curline_len() + 1
			line = Alloc(int(ind_len + line_len))
			p = line
		}
	}
	Memmove(p, ml_get_curline(), int(uint64(line_len)))
	ml_replace(curwin.w_cursor.lnum, line, FALSE)
	curwin.w_cursor.col = ind_len
	return true
}

