	var same int32
	var keys_unescaped Ptr[byte]
	var keys_unescaped_len usize
	var hash int32
	var t3 int32
	var hash_2 int32
	var t4 int32
	var newstr Ptr[byte]
	var new_hash int32
	var t5 int32

	mp_result = [2]*S_mapblock{}
	len_ = 0
	keys_buf = Ptr[byte]{}
	alt_keys_buf = Ptr[byte]{}
	arg_buf = Ptr[byte]{}
	retval = 0
	unique = false
	nowait = false
	silent = false
	special = false
	did_simplify = FALSE
	unmap_lhs_only = false
	keys = arg
	map_table = maphash
	abbr_table = Addr(&first_abbr)
	if maptype == MAPTYPE_UNMAP_LHS {
		unmap_lhs_only = true
		maptype = MAPTYPE_UNMAP
	}
	if maptype == MAPTYPE_NOREMAP {
		noremap = -1
	} else {
		noremap = REMAP_YES
	}
	for {
		if musl_strncmp(keys, S("<buffer>"), 8) == 0 {
			keys = skipwhite(keys.Add(8))
			map_table = View(curbuf.b_maphash[:])
			abbr_table = Addr(&curbuf.b_first_abbr)
			continue
		}
		if musl_strncmp(keys, S("<nowait>"), 8) == 0 {
			keys = skipwhite(keys.Add(8))
			nowait = true
			continue
		}
		if musl_strncmp(keys, S("<silent>"), 8) == 0 {
			keys = skipwhite(keys.Add(8))
			silent = true
			continue
		}
		if musl_strncmp(keys, S("<special>"), 9) == 0 {
			keys = skipwhite(keys.Add(9))
			special = true
			continue
		}
		if musl_strncmp(keys, S("<unique>"), 8) == 0 {
			keys = skipwhite(keys.Add(8))
			unique = true
			continue
		}
		break
	}
	validate_maphash()
	p = keys
	do_backslash = vim_strchr(p_cpo, CPO_BSLASH).Nil()
	for (p.Get() != 0) && ((maptype == MAPTYPE_UNMAP) || !((int32(p.Get()) == (' ')) || (int32(p.Get()) == 9))) {
		if ((int32(p.At(0)) == Ctrl_V) || (do_backslash && (int32(p.At(0)) == 92))) && (int32(p.At(1)) != NUL) {
			p = p.Add(1)
		}
		p = p.Add(1)
	}
	if int32(p.Get()) != NUL {
		t1 = p
		p = p.Add(1)
		t1.Put(NUL)
	}
	p = skipwhite(p)
	rhs = p
