func check_mark(pos Ptr[pos_T]) bool {
	if pos.Nil() {
		emsg(gettext_(e_unknown_mark))
		return false
	}
	if pos.P().lnum <= 0 {
		if pos.P().lnum == 0 {
			emsg(gettext_(e_mark_not_set))
		}
		return false
	}
	if pos.P().lnum > curbuf.b_ml.ml_line_count {
		emsg(gettext_(e_mark_has_invalid_line_number))
		return false
	}
	return true
}

func clrallmarks(buf *S_file_buffer) {
	var i int32 = 0
	for ; i < (('z' - 'a') + 1); i++ {
		buf.b_namedm[int(i)].lnum = 0
	}
	buf.b_op_start.lnum = 0
	buf.b_op_end.lnum = 0
	buf.b_last_cursor.lnum = 1
	buf.b_last_cursor.col = 0
	buf.b_last_cursor.coladd = 0
	buf.b_last_insert.lnum = 0
	buf.b_last_change.lnum = 0
	buf.b_changelistlen = 0
}

func mark_line(mp Ptr[pos_T], lead_len int32) Ptr[byte] {
	var s Ptr[byte]
	var p Ptr[byte]
	var len_ int32
	if (mp.P().lnum == 0) || (mp.P().lnum > curbuf.b_ml.ml_line_count) {
		return vim_strsave(S("-invalid-"))
	}
	s = vim_strnsave(skipwhite(ml_get(mp.P().lnum)), usize(Columns*5))
	len_ = 0
	p = s
	for ; int32(p.Get()) != NUL; p = p.Add(int(utfc_ptr2len(p))) {
		len_ += ptr2cells(p)
		if int64(len_) >= (Columns - int64(lead_len)) {
			break
		}
	}
	p.Put(NUL)
	return s
}

func ex_marks(eap *S_exarg) {
	arg := eap.arg
	var i int32
	var posp Ptr[pos_T]
	var startp Ptr[pos_T]
	var endp Ptr[pos_T]
	if !arg.Nil() && (int32(arg.Get()) == NUL) {
		arg = Ptr[byte]{}
	}
	show_one_mark(39, arg, Addr(&curwin.w_pcmark), Ptr[byte]{}, TRUE)
	i = 0
	for ; i < (('z' - 'a') + 1); i++ {
		show_one_mark(i+'a', arg, View(curbuf.b_namedm[:]).Add(int(i)), Ptr[byte]{}, TRUE)
	}
	show_one_mark('"', arg, Addr(&curbuf.b_last_cursor), Ptr[byte]{}, TRUE)
	show_one_mark('[', arg, Addr(&curbuf.b_op_start), Ptr[byte]{}, TRUE)
	show_one_mark(']', arg, Addr(&curbuf.b_op_end), Ptr[byte]{}, TRUE)
	show_one_mark('^', arg, Addr(&curbuf.b_last_insert), Ptr[byte]{}, TRUE)
	show_one_mark('.', arg, Addr(&curbuf.b_last_change), Ptr[byte]{}, TRUE)
	startp = Addr(&curbuf.b_visual.vi_start)
	endp = Addr(&curbuf.b_visual.vi_end)
	var t2 bool
	if startp.P().lnum != endp.P().lnum {
		t2 = startp.P().lnum < endp.P().lnum
	} else {
		var t1 bool
		if startp.P().col != endp.P().col {
			t1 = startp.P().col < endp.P().col
		} else {
			t1 = startp.P().coladd < endp.P().coladd
		}
		t2 = t1
	}
	if (t2 || (endp.P().lnum == 0)) && (startp.P().lnum != 0) {
		posp = startp
	} else {
		posp = endp
	}
	show_one_mark('<', arg, posp, Ptr[byte]{}, TRUE)
	var t3 Ptr[pos_T]
	if posp == startp {
		t3 = endp
	} else {
		t3 = startp
	}
	show_one_mark('>', arg, t3, Ptr[byte]{}, TRUE)
	show_one_mark(-1, arg, Ptr[pos_T]{}, Ptr[byte]{}, FALSE)
}

func show_one_mark(c int32, arg Ptr[byte], p Ptr[pos_T], name_arg Ptr[byte], current int32) {
	name := name_arg
	if c == -1 {
		if show_one_mark_did_title {
			show_one_mark_did_title = false
		} else {
			if arg.Nil() {
				msg(gettext_(S("No marks set")))
			} else {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_no_marks_matching_str), arg)
				emsg(iobuff_or(gettext_(e_no_marks_matching_str)))
			}
		}
	} else if ((got_int == 0) && (arg.Nil() || !vim_strchr(arg, c).Nil())) && (p.P().lnum != 0) {
		if name.Nil() && (current != 0) {
			name = mark_line(p, 15)
		}
		if !message_filtered(name) {
			if !show_one_mark_did_title {
				msg_puts_title(gettext_(S("\nmark line  col file/text")))
				show_one_mark_did_title = true
			}
			msg_putchar(10)
			if got_int == 0 {
				vim_snprintf(IObuff, 1025, S(" %c %6ld %4d "), c, p.P().lnum, p.P().col)
				msg_outtrans(IObuff)
				if !name.Nil() {
					var t1 int32
					if current != 0 {
						t1 = highlight_attr[3]
					} else {
						t1 = 0
					}
					msg_outtrans_attr(name, t1)
				}
			}
			out_flush()
		}
	}
}

func ex_delmarks(eap *S_exarg) {
	var p Ptr[byte]
	var from int32
	var to int32
	var i int32
	if (int32(eap.arg.Get()) == NUL) && (eap.forceit != 0) {
		clrallmarks(curbuf)
	} else if eap.forceit != 0 {
		emsg(gettext_(e_invalid_argument))
	} else if int32(eap.arg.Get()) == NUL {
		emsg(gettext_(e_argument_required))
	} else {
		p = eap.arg
		for ; int32(p.Get()) != NUL; p = p.Add(1) {
			if (uint32(p.Get()) - 'a') < 26 {
				if int32(p.At(1)) == '-' {
					from = int32(p.Get())
					to = int32(p.At(2))
					if !((uint32(p.At(2)) - 'a') < 26) || (to < from) {
						vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), p)
						emsg(iobuff_or(gettext_(e_invalid_argument_str)))
						return
					}
					p = p.Add(2)
				} else {
					to = int32(p.Get())
					from = to
				}
				i = from
				for ; i <= to; i++ {
					curbuf.b_namedm[int(i-'a')].lnum = 0
				}
			} else {
				switch p.Get() {
				case '"':
					curbuf.b_last_cursor.lnum = 0
				case '^':
					curbuf.b_last_insert.lnum = 0
				case '.':
					curbuf.b_last_change.lnum = 0
				case '[':
					curbuf.b_op_start.lnum = 0
				case ']':
					curbuf.b_op_end.lnum = 0
				case '<':
					curbuf.b_visual.vi_start.lnum = 0
				case '>':
					curbuf.b_visual.vi_end.lnum = 0
				case ' ':
				default:
					vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), p)
					emsg(iobuff_or(gettext_(e_invalid_argument_str)))
					return
				}
			}
		}
	}
}

func ex_changes(eap *S_exarg) {
	var i int32
	var name Ptr[byte]
	msg_puts_title(gettext_(S("\nchange line  col text")))
	i = 0
	for ; (i < curbuf.b_changelistlen) && (got_int == 0); i++ {
		if curbuf.b_changelist[int(i)].lnum != 0 {
			msg_putchar(10)
			if got_int != 0 {
				break
			}
			var t1 int32
			if i == curwin.w_changelistidx {
				t1 = '>'
			} else {
				t1 = ' '
			}
			var t2 int32
			if i > curwin.w_changelistidx {
				t2 = i - curwin.w_changelistidx
			} else {
				t2 = curwin.w_changelistidx - i
			}
			vim_snprintf(IObuff, 1025, S("%c %3d %5ld %4d "), t1, t2, curbuf.b_changelist[int(i)].lnum, curbuf.b_changelist[int(i)].col)
			msg_outtrans(IObuff)
			name = mark_line(View(curbuf.b_changelist[:]).Add(int(i)), 17)
			msg_outtrans_attr(name, highlight_attr[3])
			ui_breakcheck()
		}
		out_flush()
	}
	if curwin.w_changelistidx == curbuf.b_changelistlen {
		msg_puts(S("\n>"))
	}
}

