func utf_class_buf(c int32, buf *S_file_buffer) int32 {
	var bot int32 = 0
	var top int32 = (852 / 12) - 1
	var mid int32
	if c < 0x100 {
		if (((c == (' ')) || (c == 9)) || (c == NUL)) || (c == 0xa0) {
			return 0
		}
		if vim_iswordc_buf(c, buf) {
			return 2
		}
		return 1
	}
	if intable(emoji_all, 2336, c) {
		return 3
	}
	for top >= bot {
		mid = (bot + top) / 2
		if utf_class_buf_classes[int(mid)].last < uint32(c) {
			bot = mid + 1
		} else if utf_class_buf_classes[int(mid)].first > uint32(c) {
			top = mid - 1
		} else {
			return int32(utf_class_buf_classes[int(mid)].class)
		}
	}
	return 2
}

func utf_ambiguous_width(c int32) bool {
	return (c >= 0x80) && (intable(ambiguous, 2864, c) || intable(emoji_all, 2336, c))
}

func utf_convert(a int32, table Ptr[convertStruct], tableSize int32) int32 {
	var start int32
	var mid int32
	var end int32
	var entries int32 = int32(uint64(tableSize) / 16)
	start = 0
	end = entries
	for start < end {
		mid = (end + start) / 2
		if table.Ref(int(mid)).rangeEnd < a {
			start = mid + 1
		} else {
			end = mid
		}
	}
	if (((start < entries) && (table.Ref(int(start)).rangeStart <= a)) && (a <= table.Ref(int(start)).rangeEnd)) && (((a - table.Ref(int(start)).rangeStart) % table.Ref(int(start)).step) == 0) {
		return (a + table.Ref(int(start)).offset)
	} else {
		return a
	}
}

func utf_fold(a int32) int32 {
	if a < 0x80 {
		var t1 int32
		if (a >= 0x41) && (a <= 0x5a) {
			t1 = a + 32
		} else {
			t1 = a
		}
		return t1
	}
	return utf_convert(a, foldCase, 3296)
}

func musl_towupper(a int32) int32 {
	return utf_convert(a, toUpper, 3184)
}

func musl_towlower(a int32) int32 {
	return utf_convert(a, toLower, 2928)
}

func utf_toupper(a int32) int32 {
	if (a < 128) && ((cmp_flags & CMP_KEEPASCII) != 0) {
		var t1 int32
		if (a < 'a') || (a > 'z') {
			t1 = a
		} else {
			t1 = a - ('a' - 'A')
		}
		return t1
	}
	if (cmp_flags & CMP_INTERNAL) == 0 {
		return musl_towupper(a)
	}
	if a < 128 {
		return musl_toupper(int32(byte(a)))
	}
	return utf_convert(a, toUpper, 3184)
}

func utf_islower(a int32) bool {
	return (utf_toupper(a) != a) || (a == 0xdf)
}

func utf_tolower(a int32) int32 {
	if (a < 128) && ((cmp_flags & CMP_KEEPASCII) != 0) {
		var t1 int32
		if (a < 'A') || (a > 'Z') {
			t1 = a
		} else {
			t1 = a + ('a' - 'A')
		}
		return t1
	}
	if (cmp_flags & CMP_INTERNAL) == 0 {
		return musl_towlower(a)
	}
	if a < 128 {
		return musl_tolower(int32(byte(a)))
	}
	return utf_convert(a, toLower, 2928)
}

func utf_isupper(a int32) bool {
	return (utf_tolower(a) != a)
}

func utf_strnicmp(s1 Ptr[byte], s2 Ptr[byte], n1 usize, n2 usize) int32 {
	var c1 int32
	var c2 int32
	var cdiff int32
	var buffer Ptr[byte] = Mk[byte](6)
	for {
		c1 = utf_safe_read_char_adv(&s1, &n1)
		c2 = utf_safe_read_char_adv(&s2, &n2)
		if (c1 <= 0) || (c2 <= 0) {
			break
		}
		if c1 == c2 {
			continue
		}
		cdiff = utf_fold(c1) - utf_fold(c2)
		if cdiff != 0 {
			return cdiff
		}
	}
	if (c1 == 0) || (c2 == 0) {
		if (c1 == 0) && (c2 == 0) {
			return 0
		}
		var t1 int32
		if c1 == 0 {
			t1 = -1
		} else {
			t1 = 1
		}
		return t1
	}
	if (c1 != -1) && (c2 == -1) {
		n1 = usize(utf_char2bytes(utf_fold(c1), buffer))
		s1 = buffer
	} else if (c2 != -1) && (c1 == -1) {
		n2 = usize(utf_char2bytes(utf_fold(c2), buffer))
		s2 = buffer
	}
	for (((n1 > 0) && (n2 > 0)) && (int32(s1.Get()) != NUL)) && (int32(s2.Get()) != NUL) {
		cdiff = int32(s1.Get()) - int32(s2.Get())
		if cdiff != 0 {
			return cdiff
		}
		s1 = s1.Add(1)
		s2 = s2.Add(1)
		n1--
		n2--
	}
	if (n1 > 0) && (int32(s1.Get()) == NUL) {
		n1 = 0
	}
	if (n2 > 0) && (int32(s2.Get()) == NUL) {
		n2 = 0
	}
	if (n1 == 0) && (n2 == 0) {
		return 0
	}
	var t2 int32
	if n1 == 0 {
		t2 = -1
	} else {
		t2 = 1
	}
	return t2
}

func mb_strnicmp2(s1 Ptr[byte], s2 Ptr[byte], n1 usize, n2 usize) int32 {
	if n1 == n2 {
		return mb_strnicmp(s1, s2, n1)
	} else {
		return utf_strnicmp(s1, s2, n1, n2)
	}
}

func mb_strnicmp(s1 Ptr[byte], s2 Ptr[byte], nn usize) int32 {
	return utf_strnicmp(s1, s2, nn, nn)
}

func show_utf8() {
	var len_ int32
	var rlen int32 = 0
	var line Ptr[byte]
	var clen int32
	var i int32
	line = ml_get_cursor()
	len_ = utfc_ptr2len(line)
	if len_ == 0 {
		msg(S("NUL"))
		return
	}
	clen = 0
	i = 0
	for ; i < len_; i++ {
		if clen == 0 {
			if i > 0 {
				musl_strcpy(IObuff.Add(int(rlen)), S("+ "))
				rlen += 2
			}
			clen = utf_ptr2len(line.Add(int(i)))
		}
		var t1 int32
		if int32(line.At(int(i))) == NL {
			t1 = NUL
		} else {
			t1 = int32(line.At(int(i)))
		}
		vim_snprintf(IObuff.Add(int(rlen)), uint64((1025 - rlen)), S("%02x "), t1)
		clen--
		rlen += int32(musl_strlen(IObuff.Add(int(rlen))))
		if rlen > 1005 {
			break
		}
	}
	msg(IObuff)
}

func utf_head_off(base Ptr[byte], p Ptr[byte]) int32 {
	var q Ptr[byte]
	var s Ptr[byte]
	var c int32
	var len_ int32
	if int32(p.Get()) < 0x80 {
		return 0
	}
	q = p
	for ; ; q = q.Add(-1) {
		s = q
		for ; (int32(s.At(1)) & 0xc0) == 0x80; s = s.Add(1) {
		}
		for q.Gt(base) && ((int32(q.Get()) & 0xc0) == 0x80) {
			q = q.Add(-1)
		}
		len_ = int32(utf8len_tab[int(q.Get())])
		if (len_ != int32((int64(s.Sub(q)) + 1))) && (len_ != int32((int64(p.Sub(q)) + 1))) {
			return 0
		}
		if q.Le(base) {
			break
		}
		c = utf_ptr2char(q)
		if utf_iscomposing(c) {
			continue
		}
		break
	}
	return int32(int64(p.Sub(q)))
}

func mb_copy_char(fp *Ptr[byte], tp *Ptr[byte]) {
	l := utfc_ptr2len((*fp))
	Memmove((*tp), (*fp), int(uint64(l)))
	*tp = (*tp).Add(int(l))
	*fp = (*fp).Add(int(l))
}

func mb_off_next(base Ptr[byte], p Ptr[byte]) int32 {
	head_off := utf_head_off(base, p)
	if head_off == 0 {
		return 0
	}
	return utfc_ptr2len(p.Add(-int(head_off))) - head_off
}

func utf_find_illegal() {
	var pos pos_T
	var p Ptr[byte]
	var len_ int32

	pos = curwin.w_cursor
	curwin.w_cursor.coladd = 0
	for {
		p = ml_get_cursor()
		for int32(p.Get()) != NUL {
			len_ = utf_ptr2len(p)
			if (int32(p.Get()) >= 0x80) && ((len_ == 1) || (utf_char2len(utf_ptr2char(p)) != len_)) {
				curwin.w_cursor.col += int32(int64(p.Sub(ml_get_cursor())))
				curwin.w_set_curswant = true
				goto theend
			}
			p = p.Add(int(len_))
		}
		if curwin.w_cursor.lnum == curbuf.b_ml.ml_line_count {
			break
		}
		curwin.w_cursor.lnum++
		curwin.w_cursor.col = 0
	}
	curwin.w_cursor = pos
	beep_flush()
theend:
}

