func ml_get_buf(buf *S_file_buffer, lnum linenr_T, will_change int32) Ptr[byte] {
	var hp *S_block_hdr
	var dp *S_data_block
	if lnum > buf.b_ml.ml_line_count {
		if ml_get_buf_recursive == 0 {
			ml_get_buf_recursive++
			vim_snprintf(IObuff, emsg_iobuff_room(), e_ml_get_invalid_lnum_nr, lnum)
			iemsg(iobuff_or(e_ml_get_invalid_lnum_nr))
			ml_get_buf_recursive--
		}
		ml_flush_line(buf)
		return ml_get_invalid(buf, lnum)
	}
	if lnum <= 0 {
		lnum = 1
	}
	if buf.b_ml.ml_root == nil {
		buf.b_ml.ml_line_len = 1
		buf.b_ml.ml_line_textlen = buf.b_ml.ml_line_len
		return S("")
	}
	if buf.b_ml.ml_line_lnum != lnum {
		var idx int32
		ml_flush_line(buf)
		hp = ml_find_line(buf, lnum, ML_FIND)
		if hp == nil {
			if ml_get_buf_recursive == 0 {
				ml_get_buf_recursive++
				get_trans_bufname(buf)
				shorten_dir(NameBuff)
				vim_snprintf(IObuff, emsg_iobuff_room(), e_ml_get_cannot_find_line_nr_in_buffer_nr_str, lnum, buf.b_fnum, NameBuff)
				iemsg(iobuff_or(e_ml_get_cannot_find_line_nr_in_buffer_nr_str))
				ml_get_buf_recursive--
			}
			return ml_get_invalid(buf, lnum)
		}
		dp = hp.bh_data
		idx = int32(lnum - buf.b_ml.ml_locked_low)
		buf.b_ml.ml_line_ptr = dp.db_line[int(idx)].dl_text
		buf.b_ml.ml_line_len = dp.db_line[int(idx)].dl_len
		buf.b_ml.ml_line_textlen = buf.b_ml.ml_line_len
		buf.b_ml.ml_line_lnum = lnum
		buf.b_ml.ml_flags &= ^(ML_LINE_DIRTY | ML_ALLOCATED)
	}
	return buf.b_ml.ml_line_ptr
}

