func msg_start() {
	if msg_row < cmdline_row {
		msg_row = cmdline_row
	}
	if msg_silent == 0 {
		keep_msg = Ptr[byte]{}
		need_fileinfo = FALSE
	}
	if (msg_scroll == 0) && (full_screen != 0) {
		msg_row = cmdline_row
		msg_col = 0
	} else if (msg_didout != 0) || (in_echowindow != 0) {
		msg_putchar(10)
		cmdline_row = msg_row
	}
	if (msg_didany == 0) || (lines_left < 0) {
		msg_starthere()
	}
	if msg_silent == 0 {
		msg_didout = FALSE
		cursor_off()
	}
}

