func give_warning(message Ptr[byte], hl int32) {
	give_warning_with_source(message, hl, FALSE)
}

func give_warning_with_source(message Ptr[byte], hl int32, with_source int32) {
	if msg_silent != 0 {
		return
	}
	no_wait_return++
	keep_msg = Ptr[byte]{}
	if hl != 0 {
		keep_msg_attr = highlight_attr[25]
	} else {
		keep_msg_attr = 0
	}
	if with_source != 0 {
		msg_start()
		msg_source(highlight_attr[25])
		msg_puts(S(" "))
		msg_puts_attr(message, highlight_attr[25]|MSG_HIST)
		msg_clr_eos()
		msg_end()
	} else if (msg_attr(message, keep_msg_attr) != 0) && (msg_scrolled == 0) {
		set_keep_msg(message, keep_msg_attr)
	}
	msg_didout = FALSE
	msg_nowait = TRUE
	msg_col = 0
	no_wait_return--
}

func msg_advance(col int32) {
	if msg_silent != 0 {
		msg_col = col
		return
	}
	if col >= cmdline_width {
		col = cmdline_width - 1
	}
	for msg_col < col {
		msg_putchar(' ')
	}
}

