func ask_yesno(str Ptr[byte], direct int32) int32 {
	var r int32 = ' '
	save_State := State
	if exiting != 0 {
		term_enter()
	}
	no_wait_return++
	State = MODE_CONFIRM
	no_mapping++
	allow_keys++
	for (r != 'y') && (r != 'n') {
		vim_snprintf(IObuff, iobuff_room(), S("%s (y/n)?"), str)
		msg_attr(iobuff_or(S("%s (y/n)?")), highlight_attr[17])
		if direct != 0 {
			r = get_keystroke()
		} else {
			r = plain_vgetc()
		}
		if (r == Ctrl_C) || (r == ESC) {
			r = 'n'
		}
		msg_putchar(r)
		out_flush()
	}
	no_wait_return--
	State = save_State
	no_mapping--
	allow_keys--
	return r
}

func get_keystroke() int32 {
	var buf Ptr[byte] = Ptr[byte]{}
	var buflen int32 = 150
	var maxlen int32
	var len_ int32 = 0
	var n int32
	save_mapped_ctrl_c := mapped_ctrl_c
	var waited int32 = 0
	mod_mask = 0
	mapped_ctrl_c = FALSE
	for {
		cursor_on()
		out_flush()
		maxlen = ((buflen - 6) - len_) / 3
		if buf.Nil() {
			buf = Alloc(int(buflen))
		} else if maxlen < 10 {
			t_buf := buf
			t_buflen := buflen
			buflen += 100
			buf = host_alloc(usize(buflen)).(Ptr[byte])
			Memmove(buf, t_buf, int(t_buflen))
			maxlen = ((buflen - 6) - len_) / 3
		}
		if buf.Nil() {
			do_outofmem_msg(uint64(buflen))
			return ESC
		}
		var t1 int64
		if len_ == 0 {
			t1 = -1
		} else {
			t1 = 100
		}
		n = ui_inchar(buf.Add(int(len_)), maxlen, t1, 0)
		if n > 0 {
			n = fix_input_buffer(buf.Add(int(len_)), n)
			len_ += n
			waited = 0
		} else if len_ > 0 {
			waited++
		}
		n = check_termcode(1, buf, buflen, &len_)
		var t4 bool = n < 0
		if t4 {
			var t3 bool = p_ttimeout == 0
			if !t3 {
				var t2 int64
				if p_ttm < 0 {
					t2 = p_tm
				} else {
					t2 = p_ttm
				}
				t3 = (int64(waited) * 100) < t2
			}
			t4 = t3
		}
		if t4 {
			continue
		}
		if n == KEYLEN_REMOVED {
			if ((must_redraw != 0) && (need_wait_return == 0)) && ((State & ((MODE_CMDLINE | (0x2000 | MODE_NORMAL)) | MODE_ASKMORE)) == 0) {
				update_screen(0)
				setcursor()
			}
			continue
		}
		if n > 0 {
			len_ = n
		}
		if len_ == 0 {
			continue
		}
		n = int32(buf.At(0))
		if n == 0x80 {
			var t6 int32
			if int32(buf.At(1)) == KS_SPECIAL {
				t6 = 0x80
			} else {
				var t5 int32
				if int32(buf.At(1)) == KS_ZERO {
					t5 = -(KS_ZERO + (88 << 8))
				} else {
					t5 = -(int32(buf.At(1)) + (int32(buf.At(2)) << 8))
				}
				t6 = t5
			}
			n = t6
			if (int32(buf.At(1)) == KS_MODIFIER) || (n == K_IGNORE) {
				if int32(buf.At(1)) == KS_MODIFIER {
					mod_mask = int32(buf.At(2))
				}
				len_ -= 3
				if len_ > 0 {
					Memmove(buf, buf.Add(3), int(uint64(len_)))
				}
				continue
			}
			break
		}
		if int32(mb_bytelen_tab[int(n)]) > len_ {
			continue
		}
		var t7 int32
		if len_ >= buflen {
			t7 = buflen - 1
		} else {
			t7 = len_
		}
		buf.Set(int(t7), NUL)
		n = utf_ptr2char(buf)
		if n == intr_char {
			n = ESC
		}
		break
	}
	mapped_ctrl_c = save_mapped_ctrl_c
	return merge_modifyOtherKeys(n, &mod_mask)
}

func msgmore(n int64) {
	var pn int64
	if (global_busy != 0) || !messaging() {
		return
	}
	if !keep_msg.Nil() && (keep_msg_more == 0) {
		return
	}
	if n > 0 {
		pn = n
	} else {
		pn = -n
	}
	if pn > p_report {
		if n > 0 {
			vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT(S("%ld more line"), S("%ld more lines"), uint64(pn)), pn)
		} else {
			vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT(S("%ld line less"), S("%ld fewer lines"), uint64(pn)), pn)
		}
		if got_int != 0 {
			vim_strcat(msg_buf, gettext_(S(" (Interrupted)")), MSG_BUF_LEN)
		}
		if msg(msg_buf) != 0 {
			set_keep_msg(msg_buf, 0)
			keep_msg_more = TRUE
		}
	}
}

func beep_flush() {
	if emsg_silent == 0 {
		flush_buffers(FLUSH_MINIMAL)
		vim_beep(BO_ERROR)
	}
}

func vim_beep(val uint32) {
	if (emsg_silent != 0) || (in_assert_fails != 0) {
		return
	}
	if !(((bo_flags & val) != 0) || ((bo_flags & BO_ALL) != 0)) {
		if !vim_beep_did_init || ((musl_now_ms() - vim_beep_start_tv) > 500) {
			vim_beep_did_init = true
			vim_beep_start_tv = musl_now_ms()
			if p_vb != 0 {
				out_str_cf(term_strings[39])
			} else {
				out_char(BELL)
			}
		}
	}
}

func expand_env_esc(srcp Ptr[byte], dst Ptr[byte], dstlen int32, esc_chars Ptr[byte], one int32, startstr Ptr[byte]) usize {
	var src Ptr[byte]
	dst_start := dst
	src = skipwhite(srcp)
	dstlen--
	for (src.Get() != 0) && (dstlen > 0) {
		if (int32(src.At(0)) == 92) && (int32(src.At(1)) != NUL) {
			var t1 Ptr[byte] = dst
			dst = dst.Add(1)
			var t2 Ptr[byte] = src
			src = src.Add(1)
			t1.Put(t2.Get())
			dstlen--
		}
		if dstlen > 0 {
			var t3 Ptr[byte] = dst
			dst = dst.Add(1)
			var t4 Ptr[byte] = src
			src = src.Add(1)
			t3.Put(t4.Get())
			dstlen--
		}
	}
	dst.Put(NUL)
	return uint64(int64(dst.Sub(dst_start)))
}

func prepare_to_exit() {
	windgoto(int32(Rows)-1, cmdline_col_off)
	was_full_screen := full_screen
	full_screen = TRUE
	term_leave()
	full_screen = was_full_screen
	stoptermcap()
	out_flush()
}

func preserve_exit() {
	prepare_to_exit()
	really_exiting = TRUE
	out_str(IObuff)
	screen_start()
	out_flush()
	ml_close_notmod()
	ml_close_all(FALSE)
	out_str(S("Vim: Finished.\r\n"))
	getout(1)
}

