func find_command(cmdchar int32) int32 {
	var i int32
	var idx int32
	var top int32
	var bot int32
	var c int32
	if cmdchar >= 0x100 {
		return -1
	}
	if cmdchar < 0 {
		cmdchar = -cmdchar
	}
	if cmdchar <= nv_max_linear {
		return int32(nv_cmd_idx[int(cmdchar)])
	}
	bot = nv_max_linear + 1
	top = (4656 / 24) - 1
	idx = -1
	for bot <= top {
		i = (top + bot) / 2
		c = nv_cmds[int(nv_cmd_idx[int(i)])].cmd_char
		if c < 0 {
			c = -c
		}
		if cmdchar == c {
			idx = int32(nv_cmd_idx[int(i)])
			break
		}
		if cmdchar > c {
			bot = i + 1
		} else {
			top = i - 1
		}
	}
	return idx
}

