			musl_strcpy(newp.Add(int(bd.textcol)).Add(int(bd.startspaces)).Add(int(bd.endspaces)), oldp.Add(int(bd.textcol)).Add(int(bd.textlen)))
			ml_replace(lnum, newp, FALSE)
