func op_tilde(oap *S_oparg_S) {
	var one_change int32

	var pos pos_T
	var bd S_block_def
	var did_change int32 = FALSE
	if !u_save((oap.start.lnum - 1), (oap.end.lnum + 1)) {
		return
	}
	pos = oap.start
	if oap.block_mode != 0 {
		for ; pos.lnum <= oap.end.lnum; pos.lnum++ {
			block_prep(oap, &bd, pos.lnum, FALSE)
			pos.col = bd.textcol
			one_change = swapchars(oap.op_type, &pos, bd.textlen)
			did_change |= one_change
		}
		if did_change != 0 {
			changed_lines(oap.start.lnum, 0, oap.end.lnum+1, 0)
		}
	} else {
		if oap.motion_type == MLINE {
			oap.start.col = 0
			pos.col = 0
			oap.end.col = ml_get_len(oap.end.lnum)
			if oap.end.col != 0 {
				oap.end.col--
			}
		} else if oap.inclusive == 0 {
			dec(&oap.end)
		}
		if pos.lnum == oap.end.lnum {
			did_change = swapchars(oap.op_type, &pos, (oap.end.col-pos.col)+1)
		} else {
			for {
				var t1 int32
				if pos.lnum == oap.end.lnum {
					t1 = oap.end.col + 1
				} else {
					t1 = ml_get_pos_len(&pos)
				}
				did_change |= swapchars(oap.op_type, &pos, t1)
				var t3 bool
				if oap.end.lnum != pos.lnum {
					t3 = oap.end.lnum < pos.lnum
				} else {
					var t2 bool
					if oap.end.col != pos.col {
						t2 = oap.end.col < pos.col
					} else {
						t2 = oap.end.coladd < pos.coladd
					}
					t3 = t2
				}
				if (t3 || (((oap.end.lnum == pos.lnum) && (oap.end.col == pos.col)) && (oap.end.coladd == pos.coladd))) || (inc(&pos) == -1) {
					break
				}
			}
		}
		if did_change != 0 {
			changed_lines(oap.start.lnum, oap.start.col, oap.end.lnum+1, 0)
		}
	}
	if (did_change == 0) && (oap.is_VIsual != 0) {
		redraw_curbuf_later(UPD_INVERTED)
	}
	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = oap.start
		curbuf.b_op_end = oap.end
	}
	if oap.line_count > p_report {
		vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("%ld line changed"), S("%ld lines changed"), uint64(oap.line_count)), oap.line_count)
		msg(iobuff_or(NGETTEXT(S("%ld line changed"), S("%ld lines changed"), uint64(oap.line_count))))
	}
}

func swapchars(op_type int32, pos *pos_T, length int32) int32 {
	var todo int32
	var did_change int32 = 0
	todo = length
	for ; todo > 0; todo-- {
		len_ := utfc_ptr2len(ml_get_pos(pos))
		if len_ > 0 {
			todo -= len_ - 1
		}
		did_change |= B2i(swapchar(op_type, pos))
		if inc(pos) == -1 {
			break
		}
	}
	return did_change
}

func swapchar(op_type int32, pos *pos_T) bool {
	var c int32
	var nc int32
	c = gchar_pos(pos)
	if (((op_type == OP_UPPER) || (op_type == OP_NOP)) || (op_type == OP_TILDE)) && (c == 0xdf) {
		sp := curwin.w_cursor
		curwin.w_cursor = (*pos)
		del_char(FALSE)
		ins_char(0x1E9E)
		curwin.w_cursor = sp
		return true
	}
	nc = c
	if vim_islower(c) {
		if op_type != OP_LOWER {
			nc = vim_toupper(c)
		}
	} else if vim_isupper(c) {
		if op_type != OP_UPPER {
			nc = vim_tolower(c)
		}
	}
	if nc != c {
		if (c >= 0x80) || (nc >= 0x80) {
			sp_2 := curwin.w_cursor
			curwin.w_cursor = (*pos)
			del_bytes(int64(utf_ptr2len(ml_get_cursor())), FALSE, FALSE)
			ins_char(nc)
			curwin.w_cursor = sp_2
		} else {
			pbyte((*pos), nc)
		}
		return true
	}
	return false
}

