func do_set(arg_start Ptr[byte], opt_flags int32) bool {
	var arg Ptr[byte]
	var i int32
	var did_show int32
	var stopopteval int32
	var errmsg Ptr[byte]
	var errbuf Ptr[byte]
	var startarg Ptr[byte]
	var t1 Ptr[byte]

	arg = arg_start
	did_show = FALSE
	if int32(arg.Get()) == NUL {
		showoptions(0, opt_flags)
		did_show = TRUE
		goto theend
	}
	for int32(arg.Get()) != NUL {
		if (musl_strncmp(arg, S("all"), 3) == 0) && !(((uint32(arg.At(3)) - 'A') < 26) || ((uint32(arg.At(3)) - 'a') < 26)) {
			arg = arg.Add(3)
			if int32(arg.Get()) == '&' {
				arg = arg.Add(1)
				set_options_default(OPT_FREE | opt_flags)
				didset_options()
				didset_options2()
				redraw_all_later(UPD_CLEAR)
			} else {
				showoptions(1, opt_flags)
				did_show = TRUE
			}
		} else if musl_strncmp(arg, S("termcap"), 7) == 0 {
			showoptions(2, opt_flags)
			show_termcodes(opt_flags)
			did_show = TRUE
			arg = arg.Add(7)
		} else {
			stopopteval = FALSE
			errmsg = Ptr[byte]{}
			errbuf = Mk[byte](80)
			startarg = arg
			errmsg = do_set_option(opt_flags, &arg, arg_start, &startarg, &did_show, &stopopteval, errbuf, ERR_BUFLEN)
			if stopopteval != 0 {
				break
			}
			i = 0
			for ; i < 2; i++ {
				for (int32(arg.Get()) != NUL) && !((int32(arg.Get()) == (' ')) || (int32(arg.Get()) == 9)) {
					t1 = arg
					arg = arg.Add(1)
					if (int32(t1.Get()) == 92) && (int32(arg.Get()) != NUL) {
						arg = arg.Add(1)
					}
				}
				arg = skipwhite(arg)
				if int32(arg.Get()) != '=' {
					break
				}
			}
			if !errmsg.Nil() {
				i = vim_snprintf(IObuff, 1025, S("%s"), gettext_(errmsg)) + 2
				if (int64(i) + int64(arg.Sub(startarg))) < 1025 {
					musl_strcpy(IObuff.Add(int(i)).Add(-2), S(": "))
					Memmove(IObuff.Add(int(i)), startarg, int(int64(arg.Sub(startarg))))
					IObuff.Set(int(int64(i)+int64(arg.Sub(startarg))), NUL)
				}
				trans_characters(IObuff, 1025)
				no_wait_return++
				emsg(IObuff)
				no_wait_return--
				return false
			}
		}
		arg = skipwhite(arg)
	}
theend:
	return true
}

func did_set_option(opt_idx int32, opt_flags int32, new_value int32, value_checked int32) {
	var flagsp *long_u
	var flagsp_local *long_u = nil
	both := (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0
	options.Ref(int(opt_idx)).flags |= P_WAS_SET
	flagsp = &options.Ref(int(opt_idx)).flags
	if both {
		flagsp_local = &options.Ref(int(opt_idx)).flags
	}
	if (value_checked == 0) && (secure != 0) {
		*flagsp = (*flagsp) | P_INSECURE
		if flagsp_local != nil {
			*flagsp_local = (*flagsp_local) | P_INSECURE
		}
	} else if new_value != 0 {
		*flagsp = (*flagsp) & 18446744073701163007
		if flagsp_local != nil {
			*flagsp_local = (*flagsp_local) & 18446744073701163007
		}
	}
}

func option_expand(opt_idx int32, val Ptr[byte]) Ptr[byte] {
	if ((options.Ref(int(opt_idx)).flags & P_EXPAND) == 0) || optvar_is_null(options.Ref(int(opt_idx)).var_) {
		return Ptr[byte]{}
	}
	if !val.Nil() && (musl_strlen(val) > PATH_MAX) {
		return Ptr[byte]{}
	}
	if val.Nil() {
		val = options.Ref(int(opt_idx)).var_.ov_str.Get()
	}
	var esc bool = false
	var t1 Ptr[byte]
	if esc {
		t1 = S(" \t")
	} else {
		t1 = Ptr[byte]{}
	}
	expand_env_esc(val, NameBuff, PATH_MAX, t1, FALSE, Ptr[byte]{})
	if musl_strcmp(NameBuff, val) == 0 {
		return Ptr[byte]{}
	}
	return NameBuff
}

