func get_term_code(tname Ptr[byte]) Ptr[byte] {
	var opt_idx int32
	var varp optvar_T
	if (((int32(tname.At(0)) != 't') || (int32(tname.At(1)) != '_')) || (int32(tname.At(2)) == NUL)) || (int32(tname.At(3)) == NUL) {
		return Ptr[byte]{}
	}
	opt_idx = findoption(tname)
	if opt_idx >= 0 {
		varp = get_varp(options.Add(int(opt_idx)))
		if !optvar_is_null(varp) {
			return varp.ov_str.Get()
		}
		return Ptr[byte]{}
	}
	return find_termcode(tname.Add(2))
}

