func deathtrap(sigarg int32) {
	var i int32
	if ((deathtrap_entered == 0) && ((sigarg == SIGHUP) || (sigarg == SIGTERM))) && !vim_handle_signal(sigarg) {
		return
	}
	deathtrap_entered++
	block_autocmds()
	v_dying = deathtrap_entered
	i = 0
	for ; signal_info[int(i)].sig != -1; i++ {
		if sigarg == signal_info[int(i)].sig {
			break
		}
	}
	full_screen = FALSE
	if deathtrap_entered == 2 {
		out_str(S("Vim: Double signal, exiting\n"))
		out_flush()
		getout(1)
	}
	vim_snprintf(IObuff, 1025, S("Vim: Caught deadly signal %s\r\n"), signal_info[int(i)].name)
	preserve_exit()
}

func mch_suspend() {
	out_flush()
	term_leave()
	out_flush()
	musl_suspend()
	term_enter()
}

func mch_init() {
	Columns = 80
	Rows = 24
	out_flush()
	musl_host_init()
}

func vim_handle_signal(sig int32) bool {
	switch sig {
	case -1:
		vim_handle_signal_blocked = true
	case -2:
		vim_handle_signal_blocked = false
		if vim_handle_signal_got_signal != 0 {
			host_raise(vim_handle_signal_got_signal)
			vim_handle_signal_got_signal = 0
		}
	default:
		if !vim_handle_signal_blocked {
			return true
		}
		vim_handle_signal_got_signal = sig
		got_int = TRUE
	}
	return false
}

func vim_is_xterm(name Ptr[byte]) bool {
	if name.Nil() {
		return false
	}
	return ((((((((musl_strncasecmp(name, S("xterm"), 5) == 0) && (musl_strncasecmp(name, S("xterm-kitty"), 11) != 0)) || (musl_strncasecmp(name, S("nxterm"), 6) == 0)) || (musl_strncasecmp(name, S("kterm"), 5) == 0)) || (musl_strncasecmp(name, S("mlterm"), 6) == 0)) || (musl_strncasecmp(name, S("rxvt"), 4) == 0)) || (musl_strncasecmp(name, S("screen.xterm"), 12) == 0)) || (musl_strcmp(name, S("builtin_xterm")) == 0))
}

func exit_scroll() {
	if (newline_on_exit != 0) || (msg_didout != 0) {
		if msg_use_printf() {
			if info_message != 0 {
				host_message(S("\n"), -1, FALSE)
			} else {
				host_message(S("\r\n"), -1, TRUE)
			}
		} else {
			out_char(10)
		}
	} else {
		restore_cterm_colors()
		msg_clr_eos_force()
		windgoto(int32(Rows)-1, cmdline_col_off)
	}
}

func mch_exit(r int32) {
	exiting = TRUE
	term_leave()
	if swapping_screen() && (newline_on_exit == 0) {
		exit_scroll()
	}
	stoptermcap()
	if !swapping_screen() || (newline_on_exit != 0) {
		exit_scroll()
	}
	if full_screen != 0 {
		cursor_on()
	}
	out_flush()
	ml_close_all(TRUE)
	host_exit(r)
}

func get_stty() {
	var info ttyinfo_T
	var buf Ptr[byte] = Mk[byte](2)
	var p Ptr[byte]
	if !get_tty_info(read_cmd_fd, &info) {
		return
	}
	intr_char = info.interrupt
	buf.Set(0, byte(info.backspace))
	buf.Set(1, NUL)
	add_termcode(S("kb"), buf, FALSE)
	p = find_termcode(S("kD"))
	if (!p.Nil() && (int32(p.At(0)) == int32(buf.At(0)))) && (int32(p.At(1)) == int32(buf.At(1))) {
		do_fixdel(nil)
	}
}

func get_tty_info(fd int32, info *ttyinfo_T) bool {
	var bs int32 = 0
	var intr int32 = 0
	var cr int32 = 0
	var nlcr int32 = 0
	if musl_tty_keys(fd, &bs, &intr, &cr, &nlcr) == OK {
		info.backspace = int32(byte(bs))
		info.interrupt = int32(byte(intr))
		var t1 int32
		if cr != 0 {
			t1 = NL
		} else {
			t1 = CAR
		}
		info.enter = t1
		var t2 int32
		if nlcr != 0 {
			t2 = TRUE
		} else {
			t2 = FALSE
		}
		info.nl_does_cr = t2
		return true
	}
	return false
}

