func regtry(prog *S_regprog, col colnr_T, timed_out *int32) int64 {
	rex.input = rex.line.Add(int(col))
	rex.need_clear_subexpr = TRUE
	if regmatch(prog.program.Add(1), timed_out) == 0 {
		return 0
	}
	cleanup_subexpr()
	if rex.reg_match == nil {
		if rex.reg_startpos.Ref(0).lnum < 0 {
			rex.reg_startpos.Ref(0).lnum = 0
			rex.reg_startpos.Ref(0).col = col
		}
		if rex.reg_endpos.Ref(0).lnum < 0 {
			rex.reg_endpos.Ref(0).lnum = rex.lnum
			rex.reg_endpos.Ref(0).col = int32(int64(rex.input.Sub(rex.line)))
		} else {
			rex.lnum = rex.reg_endpos.Ref(0).lnum
		}
	} else {
		if rex.reg_startp.At(0).Nil() {
			rex.reg_startp.Set(0, rex.line.Add(int(col)))
		}
		if rex.reg_endp.At(0).Nil() {
			rex.reg_endp.Set(0, rex.input)
		}
	}
	return 1 + rex.lnum
}

