func windgoto(row int32, col int32) {
	var p Ptr[sattr_T]
	var i int32
	var plan int32
	var cost int32
	var wouldbe_col int32
	var noinvcurs int32
	var bs Ptr[byte]
	var goto_cost int32
	var attr int32
	if ScreenLines.Nil() {
		return
	}
	if (col == screen_cur_col) && (row == screen_cur_row) {
		return
	}
	if row < 0 {
		row = 0
	}
	if row >= screen_Rows {
		row = screen_Rows - 1
	}
	if col >= screen_Columns {
		col = screen_Columns - 1
	}
	if (screen_attr != 0) && (int32(term_strings[35].Get()) == NUL) {
		noinvcurs = HIGHL_COST
	} else {
		noinvcurs = 0
	}
	goto_cost = GOTO_COST + noinvcurs
	if (row >= screen_cur_row) && (int64(screen_cur_col) < Columns) {
		bs = Ptr[byte]{}
		attr = screen_attr
		if (row == screen_cur_row) && (col < screen_cur_col) {
			if term_strings[58].Get() != 0 {
				bs = term_strings[58]
			} else {
				bs = term_strings[47]
			}
			if bs.Get() != 0 {
				cost = (screen_cur_col - col) * int32(musl_strlen(bs))
			} else {
				cost = 999
			}
			if (col + 1) < cost {
				plan = PLAN_CR
				wouldbe_col = 0
				cost = 1
			} else {
				plan = PLAN_LE
				wouldbe_col = col
			}
			if noinvcurs != 0 {
				cost += noinvcurs
				attr = 0
			}
		} else if row > screen_cur_row {
			plan = PLAN_NL
			wouldbe_col = 0
			cost = (row - screen_cur_row) * 2
			if noinvcurs != 0 {
				cost += noinvcurs
				attr = 0
			}
		} else {
			plan = PLAN_WRITE
			wouldbe_col = screen_cur_col
			cost = 0
		}
		i = col - wouldbe_col
		if i > 0 {
			cost += i
		}
		if (cost < goto_cost) && (i > 0) {
			p = ScreenAttrs.Add(int(LineOffset.At(int(row)))).Add(int(wouldbe_col))
			for {
				var t2 bool = i != 0
				if t2 {
					var t1 Ptr[sattr_T] = p
					p = p.Add(1)
					t2 = int32(t1.Get()) == attr
				}
				if !t2 {
					break
				}
				i--
			}
			if i != 0 {
				p = p.Add(-1)
				if int32(p.Get()) == 0 {
					cost += noinvcurs
					for {
						var t4 bool = i != 0
						if t4 {
							var t3 Ptr[sattr_T] = p
							p = p.Add(1)
							t4 = int32(t3.Get()) == 0
						}
						if !t4 {
							break
						}
						i--
					}
				}
				if i != 0 {
					cost = 999
				}
			}
			i = wouldbe_col
			for ; i < col; i++ {
				if ScreenLinesUC.At(int(LineOffset.At(int(row))+uint32(i))) != 0 {
					cost = 999
					break
				}
			}
		}
		if cost < goto_cost {
			if plan == PLAN_LE {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				for screen_cur_col > col {
					out_str(bs)
					screen_cur_col--
				}
			} else if plan == PLAN_CR {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				out_char(13)
				screen_cur_col = 0
			} else if plan == PLAN_NL {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				for screen_cur_row < row {
					out_char(10)
					screen_cur_row++
				}
				screen_cur_col = 0
			}
			i = col - screen_cur_col
			if i > 0 {
				if (int32(term_strings[59].At(0)) != NUL) && (int32(term_strings[59].At(1)) == NUL) {
					for {
						var t5 int32 = i
						i--
						if !(t5 > 0) {
							break
						}
						out_char(uint32(term_strings[59].Get()))
					}
				} else {
					var off int32 = int32(LineOffset.At(int(row)) + uint32(screen_cur_col))
					for {
						var t6 int32 = i
						i--
						if !(t6 > 0) {
							break
						}
						if int32(ScreenAttrs.At(int(off))) != screen_attr {
							screen_stop_highlight()
						}
						out_char(uint32(ScreenLines.At(int(off))))
						off++
					}
				}
			}
		}
	} else {
		cost = 999
	}
	if cost >= goto_cost {
		if noinvcurs != 0 {
			screen_stop_highlight()
		}
		if ((row == screen_cur_row) && (col > screen_cur_col)) && (int32(term_strings[38].Get()) != NUL) {
			term_cursor_right(col - screen_cur_col)
		} else {
			term_windgoto(row, col)
		}
	}
	screen_cur_row = row
	screen_cur_col = col
}

