func ignorecase(pat Ptr[byte]) int32 {
	return ignorecase_opt(pat, p_ic, p_scs)
}

func ignorecase_opt(pat Ptr[byte], ic_in int32, scs int32) int32 {
	ic := ic_in
	if ((ic != 0) && (no_smartcase == 0)) && (scs != 0) {
		ic = B2i(!pat_has_uppercase(pat))
	}
	no_smartcase = FALSE
	return ic
}

func pat_has_uppercase(pat Ptr[byte]) bool {
	var l int32

	p := pat
	var magic_val magic_T = MAGIC_ON
	skip_regexp_ex(pat, NUL, magic_isset(), nil, nil, &magic_val)
	for int32(p.Get()) != NUL {
		l = utfc_ptr2len(p)
		if l > 1 {
			if utf_isupper(utf_ptr2char(p)) {
				return true
			}
			p = p.Add(int(l))
		} else if (int32(p.Get()) == 92) && (magic_val <= MAGIC_ON) {
			if (int32(p.At(1)) == '_') && (int32(p.At(2)) != NUL) {
				p = p.Add(3)
			} else if (int32(p.At(1)) == '%') && (int32(p.At(2)) != NUL) {
				p = p.Add(3)
			} else if int32(p.At(1)) != NUL {
				p = p.Add(2)
			} else {
				p = p.Add(1)
			}
		} else if ((int32(p.Get()) == '%') || (int32(p.Get()) == '_')) && (magic_val == MAGIC_ALL) {
			if int32(p.At(1)) != NUL {
				p = p.Add(2)
			} else {
				p = p.Add(1)
			}
		} else if vim_isupper(int32(p.Get())) {
			return true
		} else {
			p = p.Add(1)
		}
	}
	return false
}

