func parse_search_pattern_offset(pat *Ptr[byte], patlen *usize, search_delim int32, options int32, strcopy *Ptr[byte], searchstr *Ptr[byte], searchstrlen *usize, dircp *Ptr[byte], offset *S_soffset) int32 {
	var cmdlen int32 = 0
	var p Ptr[byte]
	var ps Ptr[byte]
	if (*pat).Nil() || (int32((*pat).Get()) == NUL) {
		return 0
	}
	ps = (*strcopy)
	*searchstr = (*pat)
	*searchstrlen = (*patlen)
	*dircp = Ptr[byte]{}
	p = skip_regexp_ex((*pat), search_delim, magic_isset(), strcopy, nil, nil)
	if (*strcopy) != ps {
		len_ := musl_strlen((*strcopy))
		cmdlen += int32(((*patlen) - len_))
		*pat = (*strcopy)
		*patlen = len_
		*searchstr = (*strcopy)
		*searchstrlen = len_
	}
	if int32(p.Get()) == search_delim {
		*searchstrlen = uint64(int64(p.Sub((*pat))))
		*dircp = p
		var t1 Ptr[byte] = p
		p = p.Add(1)
		t1.Put(NUL)
	}
	offset.line = FALSE
	offset.end = FALSE
	offset.off = 0
	if ((int32(p.Get()) == '+') || (int32(p.Get()) == '-')) || ((uint32(p.Get()) - '0') < 10) {
		offset.line = TRUE
	} else if ((options & SEARCH_OPT) != 0) && (((int32(p.Get()) == 'e') || (int32(p.Get()) == 's')) || (int32(p.Get()) == 'b')) {
		if int32(p.Get()) == 'e' {
			offset.end = SEARCH_END
		}
		p = p.Add(1)
	}
	if (((uint32(p.Get()) - '0') < 10) || (int32(p.Get()) == '+')) || (int32(p.Get()) == '-') {
		if ((uint32(p.Get()) - '0') < 10) || ((uint32(p.Add(1).Get()) - '0') < 10) {
			offset.off = musl_atol(p)
		} else if int32(p.Get()) == '-' {
			offset.off = -1
		} else {
			offset.off = 1
		}
		p = p.Add(1)
		for (uint32(p.Get()) - '0') < 10 {
			p = p.Add(1)
		}
	}
	cmdlen += int32(int64(p.Sub((*pat))))
	(*patlen) -= uint64(int64(p.Sub((*pat))))
	*pat = p
	return cmdlen
}

