func term_strings_not_set(idx int32) bool {
	return term_strings[int(idx)].Nil() || (term_strings[int(idx)] == empty_option)
}

func report_term_error(error_msg Ptr[byte], term Ptr[byte]) {
	var buf Ptr[byte] = Mk[byte](1024)
	if !error_msg.Nil() {
		vim_snprintf(buf, 1024, S("\r\n%s\r\n'%s%s\r\n"), error_msg, term, gettext_(S("' not known")))
	} else {
		vim_snprintf(buf, 1024, S("\r\n'%s%s\r\n"), term, gettext_(S("' not known")))
	}
	host_message(buf, -1, TRUE)
}

func match_keyprotocol(term Ptr[byte]) keyprot_T {
	var len_ int32
	var buf Ptr[byte]
	var ret keyprot_T
	var p Ptr[byte]
	var colon Ptr[byte]
	var prot keyprot_T
	var regmatch regmatch_T
	var match bool

	len_ = int32(musl_strlen(p_kpc)) + 1
	buf = Alloc(int(len_))
	ret = KEYPROTOCOL_FAIL
	p = p_kpc
	for int32(p.Get()) != NUL {
		copy_option_part(&p, buf, len_, S(","))
		colon = vim_strchr(buf, ':')
		if (colon.Nil() || (colon == buf)) || (int32(colon.At(1)) == NUL) {
			goto theend
		}
		colon.Put(NUL)
		if musl_strcmp(colon.Add(1), S("none")) == 0 {
			prot = KEYPROTOCOL_NONE
		} else if musl_strcmp(colon.Add(1), S("mok2")) == 0 {
			prot = KEYPROTOCOL_MOK2
		} else if musl_strcmp(colon.Add(1), S("kitty")) == 0 {
			prot = KEYPROTOCOL_KITTY
		} else {
			goto theend
		}
		regmatch = regmatch_T{}
		regmatch.rm_ic = TRUE
		regmatch.regprog = vim_regcomp(buf, RE_MAGIC)
		if regmatch.regprog == nil {
			goto theend
		}
		match = !term.Nil() && vim_regexec(&regmatch, term, 0)
		vim_regfree(regmatch.regprog)
		if match {
			ret = prot
			goto theend
		}
	}
	ret = KEYPROTOCOL_NONE
theend:
	return ret
}

func set_termname(term Ptr[byte]) bool {
	var width int32 = 0
	var height int32 = 0
	var error_msg Ptr[byte] = Ptr[byte]{}
	var bs_p Ptr[byte]
	var del_p Ptr[byte]
	detected_8bit = FALSE
	if term_is_builtin(term) {
		term = term.Add(8)
	}
	termp := find_builtin_term(term)
	if termp.Nil() {
		report_term_error(error_msg, term)
		screen_start()
		wait_return(TRUE)
		return false
	}
	out_flush()
	clear_termoptions()
	parse_builtin_tcap(term)
	if !musl_strstr(term, S("256color")).Nil() && (term_strings_not_set(KS_CCO) || (musl_atoi(term_strings[49]) < 256)) {
		apply_builtin_tcap(term, builtin_256colors, TRUE)
	}
	kpc := match_keyprotocol(term)
	apply_keyprotocol(term, kpc)
	if musl_strcmp(term, S("pcterm")) == 0 {
		term_strings[48] = S("yes")
	} else {
		term_strings[48] = empty_option
	}
	if !musl_strstr(term, S("kitty")).Nil() && (term_strings[69].Nil() || (int32(term_strings[69].Get()) == NUL)) {
		term_strings[69] = S("\x1b[>c")
	}
	get_stty()
	bs_p = find_termcode(S("kb"))
	del_p = find_termcode(S("kD"))
	if bs_p.Nil() || (int32(bs_p.Get()) == NUL) {
		bs_p = S("\x08")
		add_termcode(S("kb"), bs_p, FALSE)
	}
	if (del_p.Nil() || (int32(del_p.Get()) == NUL)) && (bs_p.Nil() || (int32(bs_p.Get()) != DEL)) {
		add_termcode(S("kD"), S("\x7f"), FALSE)
	}
	term_is_xterm = B2i(vim_is_xterm(term))
	var name Ptr[byte] = Mk[byte](3)
	name.Set(0, KS_EXTRA)
	name.Set(1, KE_FOCUSGAINED)
	name.Set(2, NUL)
	add_termcode(name, S("\x1b[I"), FALSE)
	name.Set(1, KE_FOCUSLOST)
	add_termcode(name, S("\x1b[O"), FALSE)
	need_gather = TRUE
	focus_state = MAYBE
	ttest(TRUE)
	full_screen = TRUE
	set_term_defaults()
	if starting != NO_SCREEN {
		starttermcap()
	}
	if (width <= 0) || (height <= 0) {
		width = 80
		height = 24
	}
	set_shellsize(width, height, FALSE)
	if starting != NO_SCREEN {
		if scroll_region != 0 {
			scroll_region_reset()
		}
		check_map_keycodes()
	}
	return true
}

func add_termcap_entry(name Ptr[byte], force int32) bool {
	var term Ptr[byte]
	var key int32
	if (force == 0) && !find_termcode(name).Nil() {
		return true
	}
	term = term_strings[0]
	if term.Nil() || (int32(term.Get()) == NUL) {
		return false
	}
	if term_is_builtin(term) {
		term = term.Add(8)
	}
	termp := find_builtin_term(term)
	if !termp.Nil() {
		key = -(int32(name.At(0)) + (int32(name.At(1)) << 8))
		termp = termp.Add(1)
		for termp.P().bt_entry != 0 {
			if termp.P().bt_entry == key {
				add_termcode(name, termp.P().bt_string, B2i(term_is_8bit(term)))
				return true
			}
			termp = termp.Add(1)
		}
	}
	if GaData[estack_T](&exestack).Ref(int(exestack.ga_len - 1)).es_name.Nil() {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_no_str_entry_in_termcap), name)
		emsg(iobuff_or(gettext_(e_no_str_entry_in_termcap)))
	}
	return false
}

func term_is_builtin(name Ptr[byte]) bool {
	return (musl_strncmp(name, S("builtin_"), 8) == 0)
}

func term_is_8bit(name Ptr[byte]) bool {
	return ((detected_8bit != 0) || !musl_strstr(name, S("8bit")).Nil())
}

func term_7to8bit(p Ptr[byte]) int32 {
	if int32(p.Get()) != ESC {
		return 0
	}
	if int32(p.At(1)) == '[' {
		return CSI
	} else if int32(p.At(1)) == ']' {
		return OSC
	} else if int32(p.At(1)) == 'O' {
		return 0x8f
	}
	return 0
}

func tltoa(i uint64) Ptr[byte] {
	var p Ptr[byte] = tltoa_buf.Add(15)
	p.Put(0)
	for {
		p = p.Add(-1)
		p.Put(byte(((i % 10) + '0')))
		i /= 10
		if !((i > 0) && p.Gt(tltoa_buf)) {
			break
		}
	}
	return p
}

func tgoto(cm Ptr[byte], x int32, y int32) Ptr[byte] {
	var p Ptr[byte]
	var s Ptr[byte]
	var e Ptr[byte]
	if cm.Nil() {
		return S("OOPS")
	}
	e = tgoto_buf.Add(29)
	s = tgoto_buf
	for ; s.Lt(e) && (cm.Get() != 0); cm = cm.Add(1) {
		if int32(cm.Get()) != '%' {
			var t1 Ptr[byte] = s
			s = s.Add(1)
			t1.Put(cm.Get())
			continue
		}
		cm = cm.Add(1)
		switch cm.Get() {
		case 'd':
			p = tltoa(uint64(y))
			y = x
			for p.Get() != 0 {
				var t2 Ptr[byte] = s
				s = s.Add(1)
				var t3 Ptr[byte] = p
				p = p.Add(1)
				t2.Put(t3.Get())
			}
		case 'i':
			x++
			y++
		case '+':
			var t4 Ptr[byte] = s
			s = s.Add(1)
			cm = cm.Add(1)
			t4.Put(byte((int32(cm.Get()) + y)))
			y = x
		case '%':
			var t5 Ptr[byte] = s
			s = s.Add(1)
			t5.Put(cm.Get())
		default:
			return S("OOPS")
		}
	}
	s.Put(0)
	return tgoto_buf
}

func termcapinit() {
	term := S("xterm-256color")
	set_string_option_direct(S("term"), -1, term, OPT_FREE, 0)
	set_string_default(S("term"), term)
	set_string_default(S("ttytype"), term)
	var t1 Ptr[byte]
	if !term_strings[0].Nil() {
		t1 = term_strings[0]
	} else {
		t1 = term
	}
	set_termname(t1)
}

func out_flush() {
	var len_ int32
	if out_pos == 0 {
		return
	}
	len_ = out_pos
	out_pos = 0
	ui_write(out_buf, len_)
}

func out_flush_cursor(force int32, clear_selection int32) {
	out_flush()
}

func out_char(c uint32) {
	if c == 10 {
		out_char(13)
	}
	var t1 int32 = out_pos
	out_pos++
	out_buf.Set(int(t1), byte(c))
	if (out_pos >= OUT_SIZE) || (p_wd != 0) {
		out_flush()
	}
}

func out_char_nf(c int32) int32 {
	var t1 int32 = out_pos
	out_pos++
	out_buf.Set(int(t1), byte(uint32(c)))
	if out_pos >= OUT_SIZE {
		out_flush()
	}
	return int32(uint32(c))
}

