func check_shellsize() {
	if Rows < int64(min_rows_for_all_tabpages()) {
		Rows = int64(min_rows_for_all_tabpages())
	}
	limit_screen_size()
	if int64(cmdline_row) >= Rows {
		cmdline_row = int32(Rows - 1)
	}
	if int64(msg_row) >= Rows {
		msg_row = int32(Rows - 1)
	}
}

func limit_screen_size() {
	if Columns < MIN_COLUMNS {
		Columns = MIN_COLUMNS
	} else if Columns > 10000 {
		Columns = 10000
	}
	if Rows > 1000 {
		Rows = 1000
	}
}

func win_new_shellsize() {
	if ((int64(win_new_shellsize_old_Rows) != Rows) || (int64(win_new_shellsize_old_Columns) != Columns)) || (win_new_shellsize_old_coloff != 0) {
		ui_new_shellsize()
	}
	if (int64(win_new_shellsize_old_Columns) != Columns) || (win_new_shellsize_old_coloff != 0) {
		win_new_shellsize_old_Columns = int32(Columns)
		win_new_shellsize_old_coloff = 0
		shell_new_columns()
	}
	if int64(win_new_shellsize_old_Rows) != Rows {
		if (p_window == int64(win_new_shellsize_old_Rows-1)) || ((win_new_shellsize_old_Rows == 0) && !option_was_set(S("window"))) {
			p_window = Rows - 1
		}
		win_new_shellsize_old_Rows = int32(Rows)
		shell_new_rows()
	}
}

func shell_resized() {
	set_shellsize(0, 0, FALSE)
}

func set_shellsize_inner(width int32, height int32, mustset int32) {
	if updating_screen != 0 {
		return
	}
	if (curwin.w_buffer == nil) || curwin.w_lines.Nil() {
		return
	}
	if (mustset != 0) || (!ui_get_shellsize() && (height != 0)) {
		Rows = int64(height)
		Columns = int64(width)
		check_shellsize()
		ui_set_shellsize(mustset)
	} else {
		check_shellsize()
	}
	if ((State != MODE_ASKMORE) && (State != MODE_EXTERNCMD)) && (State != MODE_CONFIRM) {
		screenclear()
	} else {
		screen_start()
	}
	if starting != NO_SCREEN {
		changed_line_abv_curs()
		invalidate_botline()
		if ((State == MODE_ASKMORE) || (State == MODE_EXTERNCMD)) || (State == MODE_CONFIRM) {
			screenalloc(FALSE)
			repeat_message()
		} else {
			if State&MODE_CMDLINE != 0 {
				update_screen(UPD_NOT_VALID)
				redrawcmdline()
			} else {
				update_topline()
				update_screen(UPD_NOT_VALID)
				if redrawing() {
					setcursor()
				}
			}
		}
		cursor_on()
	}
	out_flush()
}

func set_shellsize(width int32, height int32, mustset int32) {
	if (width < 0) || (height < 0) {
		return
	}
	if (State == (0x2000 | MODE_NORMAL)) || (State == MODE_SETWSIZE) {
		State = MODE_SETWSIZE
		return
	}
	set_shellsize_do_run = true
	if set_shellsize_busy {
		return
	}
	for set_shellsize_do_run {
		set_shellsize_do_run = false
		set_shellsize_busy = true
		set_shellsize_inner(width, height, mustset)
		set_shellsize_busy = false
	}
}

