	var key int32
	var new_slen int32
	var string_ Ptr[byte] = Mk[byte](7)
	var i int32
	var j int32
	var idx int32 = 0
	var cpo_koffset bool = !vim_strchr(p_cpo, CPO_KOFFSET).Nil()
	if need_gather != 0 {
		gather_termleader()
	}
	offset = 0
