func vim_is_input_buf_full() bool {
	return (inbufcount >= INBUFLEN)
}

func vim_is_input_buf_empty() bool {
	return (inbufcount == 0)
}

func get_input_buf() *S_growarray {
	var gap *S_growarray = new(S_growarray)
	gap.ga_data = Alloc(int(inbufcount + 1))
	Memmove(GaData[byte](gap), inbuf, int(uint64(inbufcount)))
	gap.ga_len = inbufcount
	trash_input_buf()
	return gap
}

func set_input_buf(gap *S_growarray, overwrite int32) {
	if gap == nil {
		return
	}
	if gap.ga_data != nil {
		if (overwrite != 0) || ((inbufcount + gap.ga_len) >= INBUFLEN) {
			Memmove(inbuf, GaData[byte](gap), int(gap.ga_len))
			inbufcount = gap.ga_len
		} else {
			Memmove(inbuf.Add(int(gap.ga_len)), inbuf, int(inbufcount))
			Memmove(inbuf, GaData[byte](gap), int(gap.ga_len))
			inbufcount += gap.ga_len
		}
	}
}

func trash_input_buf() {
	inbufcount = 0
}

func read_from_input_buf(buf Ptr[byte], maxlen int64) int32 {
	if inbufcount == 0 {
		fill_input_buf(TRUE)
	}
	if maxlen > int64(inbufcount) {
		maxlen = int64(inbufcount)
	}
	Memmove(buf, inbuf, int(uint64(maxlen)))
	inbufcount -= int32(maxlen)
	if (inbufcount > 0) && (maxlen > 0) {
		Memmove(inbuf, inbuf.Add(int(maxlen)), int(uint64(inbufcount)))
	}
	return int32(maxlen)
}

