func check_col(col int32) int32 {
	if col < 0 {
		return 0
	}
	if col >= screen_Columns {
		return screen_Columns - 1
	}
	return col
}

func check_row(row int32) int32 {
	if row < 0 {
		return 0
	}
	if row >= screen_Rows {
		return screen_Rows - 1
	}
	return row
}

