func u_undo(count int32) {
	if !curbuf.b_u_synced {
		u_sync(TRUE)
		count = 1
	}
	if vim_strchr(p_cpo, CPO_UNDO).Nil() {
		undo_undoes = TRUE
	} else {
		undo_undoes = B2i(undo_undoes == 0)
	}
	u_doit(count)
}

func u_redo(count int32) {
	if vim_strchr(p_cpo, CPO_UNDO).Nil() {
		undo_undoes = FALSE
	}
	u_doit(count)
}

func u_doit(startcount int32) {
	count := startcount
	if !undo_allowed() {
		return
	}
	u_newcount = 0
	u_oldcount = 0
	if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
		u_oldcount = -1
	}
	for {
		var t1 int32 = count
		count--
		if !(t1 != 0) {
			break
		}
		if undo_undoes != 0 {
			if curbuf.b_u_curhead == nil {
				curbuf.b_u_curhead = curbuf.b_u_newhead
			} else if get_undolevel() > 0 {
				curbuf.b_u_curhead = curbuf.b_u_curhead.uh_next
			}
			if (curbuf.b_u_numhead == 0) || (curbuf.b_u_curhead == nil) {
				curbuf.b_u_curhead = curbuf.b_u_oldhead
				beep_flush()
				if count == (startcount - 1) {
					if !shortmess(SHM_UNDO) {
						msg(gettext_(S("Already at oldest change")))
					}
					return
				}
				break
			}
			u_undoredo(TRUE)
		} else {
			if (curbuf.b_u_curhead == nil) || (get_undolevel() <= 0) {
				beep_flush()
				if count == (startcount - 1) {
					if !shortmess(SHM_UNDO) {
						msg(gettext_(S("Already at newest change")))
					}
					return
				}
				break
			}
			u_undoredo(FALSE)
			if curbuf.b_u_curhead.uh_prev == nil {
				curbuf.b_u_newhead = curbuf.b_u_curhead
			}
			curbuf.b_u_curhead = curbuf.b_u_curhead.uh_prev
		}
	}
	u_undo_end(undo_undoes, FALSE)
}

