func command_height() {
	var old_p_ch int32 = int32(curtab.tp_ch_used)
	frp := curwin.w_frame
	if (p_ch > int64(old_p_ch)) && (command_frame_height != 0) {
		var t1 int32
		if (p_ch - int64(old_p_ch)) < int64((frp.fr_height - frame_minheight(frp, nil))) {
			t1 = int32((p_ch - int64(old_p_ch)))
		} else {
			t1 = (frp.fr_height - frame_minheight(frp, nil))
		}
		h := t1
		frame_add_height(frp, -h)
		old_p_ch += h
	}
	if (p_ch < int64(old_p_ch)) && (command_frame_height != 0) {
		frame_add_height(frp, int32((int64(old_p_ch) - p_ch)))
	}
	win_comp_pos()
	win_fix_scroll(1)
	cmdline_row = int32(Rows - p_ch)
	redraw_cmdline = TRUE
	if (msg_scrolled == 0) && (full_screen != 0) {
		screen_fill(cmdline_row, int32(Rows), 0, int32(Columns), ' ', ' ', 0)
		msg_row = cmdline_row
	}
	curtab.tp_ch_used = p_ch
	min_set_ch = int32(p_ch)
}

