func vim_main2() int32 {
	starting = NO_BUFFERS
	no_wait_return = FALSE
	msg_scroll = FALSE
	if ((did_emsg != 0) || (msg_didout != 0)) && (int32(term_strings[42].Get()) != NUL) {
		newline_on_exit = TRUE
	}
	term_enter()
	if (need_wait_return != 0) || (msg_didany != 0) {
		wait_return(TRUE)
	}
	starttermcap()
	if scroll_region != 0 {
		scroll_region_reset()
	}
	scroll_start()
	screenclear()
	no_wait_return = TRUE
	create_windows(&params)
	setpcmark()
	shorten_fnames()
	if params.n_commands > 0 {
		exe_commands(&params)
	}
	starting = 0
	RedrawingDisabled = 0
	redraw_all_later(UPD_NOT_VALID)
	no_wait_return = FALSE
	if p_im != 0 {
		need_start_insertmode = TRUE
	}
	if restart_edit != 0 {
		stuffcharReadbuff(K_NOP)
	}
	do_redraw = TRUE
	main_loop(FALSE)
	return 0
}

