func op_pending() bool {
	return !((((((current_oap != nil) && (finish_op == 0)) && (current_oap.prev_opcount == 0)) && (current_oap.prev_count0 == 0)) && (current_oap.op_type == OP_NOP)) && (current_oap.regname == NUL))
}

func is_safe_now() bool {
	return (stuff_empty() && (typebuf.tb_len == 0)) && (global_busy == 0)
}

func may_trigger_safestate(safe int32) {
}

func work_pending() bool {
	return op_pending() || !is_safe_now()
}

func may_trigger_deferred_events() {
	if may_trigger_deferred_events_recursive {
		return
	}
	may_trigger_deferred_events_recursive = true
	update_topline()
	validate_cursor()
	may_trigger_deferred_events_recursive = false
}

func main_loop(cmdwin int32) {
	var oa S_oparg_S
	var prev_oap *S_oparg_S = current_oap
	current_oap = &oa
	clear_oparg(&oa)
	for cmdwin == 0 {
		if stuff_empty() {
			if need_wait_return != 0 {
				wait_return(FALSE)
			}
			if ((need_start_insertmode != 0) && goto_im()) && (VIsual_active == 0) {
				need_start_insertmode = FALSE
				stuffReadbuff(S("i"))
				need_fileinfo = FALSE
			}
		}
		if got_int != 0 {
			if quit_more == 0 {
				vgetc()
			}
			got_int = FALSE
		}
		msg_scroll = FALSE
		quit_more = FALSE
		if skip_redraw != 0 {
			skip_redraw = FALSE
			setcursor()
			cursor_on()
		} else if (do_redraw != 0) || stuff_empty() {
			may_trigger_deferred_events()
			may_trigger_safestate(B2i(!op_pending() && (restart_edit == 0)))
			update_topline()
			validate_cursor()
			if VIsual_active != 0 {
				update_curbuf(UPD_INVERTED)
			} else if must_redraw != 0 {
				update_screen(0)
			} else if ((redraw_cmdline != 0) || (clear_cmdline != 0)) || (redraw_mode != 0) {
				showmode()
			}
			redraw_statuslines()
			if !keep_msg.Nil() {
				p := vim_strsave(keep_msg)
				msg_hist_off = TRUE
				msg_attr(p, keep_msg_attr)
				msg_hist_off = FALSE
			}
			if need_fileinfo != 0 {
				fileinfo(FALSE, TRUE, FALSE)
				need_fileinfo = FALSE
			}
			emsg_on_display = FALSE
			did_emsg = FALSE
			msg_didany = FALSE
			may_clear_sb_text()
			showruler(FALSE)
			setcursor()
			cursor_on()
			do_redraw = FALSE
			may_make_initial_scroll_size_snapshot()
		}
		may_send_t_RK()
		update_curswant()
		normal_cmd(&oa, TRUE)
	}
	current_oap = prev_oap
}

func getout(exitval int32) {
	exiting = TRUE
	windgoto(int32(Rows)-1, 0)
	if v_dying <= 1 {
		var buf *S_file_buffer
		if (curwin.w_buffer != nil) && buf_valid(curwin.w_buffer) {
			buf = curwin.w_buffer
			if buf.b_changedtick != -1 {
				var bufref bufref_T
				set_bufref(&bufref, buf)
				if bufref_valid(&bufref) {
					buf.b_changedtick = -1
				}
			}
		}
		if curbuf.b_ml.ml_root != nil {
			var bufref_2 bufref_T
			set_bufref(&bufref_2, curbuf)
		}
	}
	if did_emsg != 0 {
		no_wait_return = FALSE
		wait_return(FALSE)
	}
	windgoto(int32(Rows)-1, 0)
	term_disable_dec()
	mch_exit(exitval)
}

func command_line_scan(parmp *mparm_T) {
	argc := parmp.argc
	argv := parmp.argv
	var argv_idx int32
	argc--
	argv = argv.Add(1)
	argv_idx = 1
	for argc > 0 {
		if int32(argv.At(0).At(0)) == '+' {
			if parmp.n_commands >= MAX_ARG_CMDS {
				mainerr(ME_EXTRA_CMD, Ptr[byte]{})
			}
			argv_idx = -1
			if int32(argv.At(0).At(1)) == NUL {
				var t1 int32 = parmp.n_commands
				parmp.n_commands++
				parmp.commands[int(t1)] = S("$")
			} else {
				var t2 int32 = parmp.n_commands
				parmp.n_commands++
				parmp.commands[int(t2)] = argv.At(0).Add(1)
			}
		} else {
			mainerr(ME_UNKNOWN_OPTION, argv.At(0))
		}
		if (argv_idx <= 0) || (int32(argv.At(0).At(int(argv_idx))) == NUL) {
			argc--
			argv = argv.Add(1)
			argv_idx = 1
		}
	}
}

func create_windows(parmp *mparm_T) {
	curbuf = curwin.w_buffer
	if curbuf.b_ml.ml_root == nil {
		open_buffer()
	}
	ui_breakcheck()
	if got_int != 0 {
		vgetc()
	}
	curbuf = curwin.w_buffer
}

func exe_commands(parmp *mparm_T) {
	var i int32
	msg_scroll = TRUE
	if curwin.w_cursor.lnum <= 1 {
		curwin.w_cursor.lnum = 0
	}
	estack_push(ETYPE_ARGS, S("command line"), 0)
	i = 0
	for ; i < parmp.n_commands; i++ {
		do_cmdline_cmd(parmp.commands[int(i)])
	}
	estack_pop()
	if curwin.w_cursor.lnum == 0 {
		curwin.w_cursor.lnum = 1
	}
	msg_scroll = FALSE
}

func mainerr(n int32, str Ptr[byte]) {
	var buf Ptr[byte] = Mk[byte](1024)
	init_longVersion()
	if !str.Nil() {
		vim_snprintf(buf, 1024, S("%s\n%s: \"%s\""), longVersion, gettext_(main_errors[int(n)]), str)
	} else {
		vim_snprintf(buf, 1024, S("%s\n%s"), longVersion, gettext_(main_errors[int(n)]))
	}
	host_message(buf, -1, TRUE)
	mch_exit(1)
}

func vim_main(argc int32, argv Ptr[Ptr[byte]]) int32 {
	params = mparm_T{}
	params.argc = argc
	params.argv = argv
	params.want_full_screen = TRUE
	common_init_1()
	common_init_2(&params)
	command_line_scan(&params)
	RedrawingDisabled++
	mch_init()
	if params.want_full_screen != 0 {
		termcapinit()
		screen_start()
	}
	ui_get_shellsize()
	win_init_size()
	cmdline_row = int32(Rows - p_ch)
	cmdline_col_off = 0
	cmdline_width = int32(Columns)
	msg_row = cmdline_row
	msg_col = 0
	screenalloc(FALSE)
	set_init_2()
	msg_scroll = TRUE
	no_wait_return = TRUE
	init_mappings()
	init_highlight(TRUE, FALSE)
	return vim_main2()
}
